/* SLM Transfert V8 — interface.
   Les données, la synchronisation, les PDF et les exports viennent de core.js / cloud.js (compatibles V7). */

/* ════════════ Utilitaires d’affichage ════════════ */
const icon=(n,cls="")=>`<svg class="${cls}" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const money0=n=>(Math.round(+n||0)).toLocaleString("fr-FR")+" €";
const num=n=>(+n||0).toLocaleString("fr-FR",{maximumFractionDigits:1});
const plural=(n,one,many)=>`${n} ${n>1?(many||one+"s"):one}`;
const ymKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
const thisMonth=()=>today().slice(0,7);
const shiftMonth=(ym,delta)=>{const[y,m]=ym.split("-").map(Number);return ymKey(new Date(y,m-1+delta,1,12))};
const monthLabel=(ym,opts={month:"long",year:"numeric"})=>new Date(ym+"-01T12:00:00").toLocaleDateString("fr-FR",opts);
const cap=s=>s?s.charAt(0).toLocaleUpperCase("fr-FR")+s.slice(1):s;
const dayLabel=d=>{if(d===today())return"Aujourd’hui";const t=new Date();t.setDate(t.getDate()+1);const tm=new Date(t-t.getTimezoneOffset()*6e4).toISOString().slice(0,10);if(d===tm)return"Demain";return cap(new Date(d+"T12:00:00").toLocaleDateString("fr-FR",{weekday:"long",day:"numeric",month:"long"}))};
const dateIn=n=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+n);return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`};
const initial=s=>String(s||"?").trim().charAt(0).toLocaleUpperCase("fr-FR")||"?";
const rideAt=c=>new Date(c.date+"T"+(c.heure||"00:00"));
const relTime=c=>{const m=Math.round((rideAt(c)-new Date())/6e4);if(m<=0)return m>-90?"maintenant":"passée";if(m<60)return`dans ${m} min`;if(m<1440)return`dans ${Math.floor(m/60)} h${m%60?" "+String(m%60).padStart(2,"0"):""}`;const d=Math.round(m/1440);return`dans ${d} j`};
const clientName=id=>{const c=cl(id);return c.nom&&c.nom!=="—"?c.nom:"Client non renseigné"};
const costKmValue=()=>+S().costKm>0?+S().costKm:0.30;
function rideMargin(c,costKm=costKmValue()){const revenue=(+c.prix||0)+(+c.pourboire||0),commission=+c.commission||0,distance=(+c.km||0)+(+c.kmVide||0),variable=distance*costKm;return{revenue,commission,distance,variable,margin:revenue-commission-variable}}
const debounce=(fn,ms=200)=>{let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms)}};
const agendaNorm=s=>String(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim();
const RM=matchMedia("(prefers-reduced-motion: reduce)");

/* ════════════ Toast, thème, splash ════════════ */
function toast(m){const t=$("#toast");if(!t)return;t.textContent=m;t.classList.add("show");clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove("show"),3400)}
function applyTheme(){const mode=db?.settings?.appearance||"system",root=document.documentElement;if(mode==="light"||mode==="dark")root.dataset.theme=mode;else delete root.dataset.theme;const dark=mode==="dark"||(mode==="system"&&matchMedia("(prefers-color-scheme: dark)").matches);const m=document.querySelector('meta[name="theme-color"]');if(m)m.content=dark?"#09130f":"#f3f7f4"}
matchMedia("(prefers-color-scheme: dark)").addEventListener?.("change",applyTheme);
function hideSplash(){const s=$("#splash");if(!s||s.classList.contains("gone"))return;s.classList.add("gone");setTimeout(()=>s.remove(),500)}
function connectionStatus(){const el=$("#connection-status");if(!el)return;if(!navigator.onLine){el.dataset.state="offline";el.title="Hors ligne : les modifications seront envoyées au retour du réseau";return}const m=String(typeof cloudMsg!=="undefined"&&cloudMsg||"").toLocaleLowerCase("fr-FR");el.dataset.state=/erreur|échec|impossible|refusée/.test(m)?"error":/attente|en cours|vérification/.test(m)?"waiting":"ok";el.title=typeof cloudMsg!=="undefined"&&cloudMsg?cloudMsg:"En ligne"}
setInterval(connectionStatus,2500);
addEventListener("online",connectionStatus);addEventListener("offline",connectionStatus);
addEventListener("scroll",()=>document.body.classList.toggle("scrolled",scrollY>8),{passive:true});

/* Compteurs animés : la valeur finale est déjà dans le DOM, l’animation part de 0 seulement à l’entrée d’une page. */
function animateCounts(root){if(RM.matches)return;root.querySelectorAll("[data-count]").forEach(el=>{const target=+el.dataset.count,fmt=el.dataset.fmt||"money0";if(!Number.isFinite(target)||target===0)return;const f=fmt==="int"?v=>Math.round(v).toLocaleString("fr-FR"):fmt==="km"?v=>Math.round(v).toLocaleString("fr-FR")+" km":money0;let st=null;const step=ts=>{if(!st)st=ts;const p=Math.min(1,(ts-st)/900),e=1-Math.pow(1-p,3);el.textContent=f(target*e);if(p<1)requestAnimationFrame(step);else el.textContent=f(target)};requestAnimationFrame(step)})}

/* ════════════ Feuilles (modales) ════════════ */
let mOpen=false,modalReturnFocus=null,modalOnClose=null;
function sheet({title="",body="",foot="",dark=false,cls="",label=""}){return`<div class="sheet ${dark?"dark":""} ${cls}" tabindex="-1"><div class="grab"></div><div class="sheet-head"><h2 id="sheet-title">${title}</h2><button class="x-btn" onclick="close_()" aria-label="Fermer">${icon("x")}</button></div><div class="sheet-body">${body}</div>${foot?`<div class="sheet-foot">${foot}</div>`:""}</div>`}
function modal(h,onClose){const m=$("#modal");if(!mOpen)modalReturnFocus=document.activeElement;modalOnClose=onClose||null;if(!/class="sheet/.test(h))h=sheet({body:`<div class="compat">${h}</div>`});m.innerHTML=h;m.classList.remove("hidden","closing");const t=m.querySelector("#sheet-title");if(t&&t.textContent.trim())m.setAttribute("aria-labelledby","sheet-title");else{m.removeAttribute("aria-labelledby");m.setAttribute("aria-label","Fenêtre")}document.body.classList.add("nolock");if(!mOpen){history.pushState({m:1},"");mOpen=true}requestAnimationFrame(()=>{m.classList.add("open");const panel=m.querySelector(".sheet");const first=[...panel.querySelectorAll('input:not([type=hidden]):not([disabled]),select,textarea')].find(x=>x.getClientRects().length&&!x.closest(".voice"));(first&&matchMedia("(min-width:720px)").matches?first:panel).focus({preventScroll:true})})}
function close_(fromPop){const m=$("#modal");if(!mOpen&&m.classList.contains("hidden"))return;try{stopVoiceRideCapture()}catch{}mOpen=false;m.classList.add("closing");m.classList.remove("open");document.body.classList.remove("nolock");const cb=modalOnClose;modalOnClose=null;setTimeout(()=>{if(!mOpen){m.classList.add("hidden");m.classList.remove("closing");m.innerHTML=""}},RM.matches?0:300);if(!fromPop&&history.state?.m){ignorePop=true;history.back()}const target=modalReturnFocus;modalReturnFocus=null;if(target?.isConnected)target.focus?.({preventScroll:true});if(cb)cb()}
let ignorePop=false;
addEventListener("popstate",()=>{if(ignorePop){ignorePop=false;return}if(mOpen)close_(true);else go()});
$("#modal").addEventListener("click",e=>{if(e.target.id==="modal")close_()});
document.addEventListener("keydown",e=>{if(!mOpen)return;if(e.key==="Escape"){e.preventDefault();close_();return}if(e.key!=="Tab")return;const panel=$("#modal .sheet");if(!panel)return;const f=[...panel.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled])')].filter(x=>x.getClientRects().length);if(!f.length)return;const a=f[0],z=f[f.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}});
/* Bouton de confirmation intégré : premier appui = demande, second appui = action. */
function confirmTap(btn,action,label="Confirmer"){if(btn.dataset.armed==="1"){action();return}btn.dataset.armed="1";const old=btn.innerHTML;btn.innerHTML=`${icon("alert")} ${label}`;btn.classList.add("danger");setTimeout(()=>{if(btn.isConnected){btn.dataset.armed="";btn.innerHTML=old}},4000)}
function askDelete(arr,id,btn){confirmTap(btn,()=>{removeRecord(arr,id);if(arr==="courses"&&tab==="course")location.hash="courses";if(arr==="clients"&&tab==="client")location.hash="clients"},"Confirmer la suppression")}

/* ════════════ Navigation ════════════ */
const NAV=[["home","home","Accueil"],["courses","cal","Courses"],["finances","wallet","Finances"],["clients","users","Clients"],["plus","more","Plus"]];
const ALIASES={agenda:"courses",history:"courses",factures:"finances",compta:"finances",billing:"premium",tools:"data"};
let tab="home",routeParam="",coursesMode="upcoming",coursesQ="",clientsQ="",finTab="overview",finMonth=thisMonth(),finScope="month",invFilter="all",lastTracked="",usageOpened=false;
const views={};
function parseRoute(){let [name,param]=(location.hash||"#home").slice(1).split("/");name=decodeURIComponent(name||"home");param=decodeURIComponent(param||"");if(name==="history")coursesMode="done";if(name==="factures")finTab="invoices";if(name==="compta")finTab="overview";name=ALIASES[name]||name;if(!Object.prototype.hasOwnProperty.call(views,name))name="home";return[name,param]}
function navHTML(){const sel=["course"].includes(tab)?"courses":tab==="client"?"clients":["documents","premium","settings","data","account","admin"].includes(tab)?"plus":tab;
  // barre basse : Accueil, Courses, +, Finances, Plus (clients accessible depuis Plus et l’accueil)
  const bottom=[NAV[0],NAV[1],null,NAV[2],NAV[4]].map(x=>x?`<a href="#${x[0]}" class="${(sel===x[0]||(x[0]==="plus"&&sel==="clients"))?"on":""}" ${sel===x[0]?'aria-current="page"':""}>${icon(x[1])}<span>${x[2]}</span></a>`:`<button class="fab" onclick="editC()" aria-label="Nouvelle course">${icon("plus")}</button>`).join("");
  $("#tabbar").innerHTML=bottom;
  const side=`<button class="btn block new" onclick="editC()">${icon("plus")} Nouvelle course</button>`+NAV.slice(0,4).map(([k,ic,l])=>`<a href="#${k}" class="${sel===k?"on":""}">${icon(ic)}${l}</a>`).join("")+`<div class="sep"></div><span class="side-label">Gestion</span>`+[["documents","file","Documents"],["data","cloud","Données et synchro"],["settings","gear","Paramètres"],["account","user","Mon compte"]].map(([k,ic,l])=>`<a href="#${k}" class="${tab===k?"on":""}">${icon(ic)}${l}</a>`).join("")+(typeof adminAccess!=="undefined"&&adminAccess?`<a href="#admin" class="${tab==="admin"?"on":""}">${icon("shield")}Administration</a>`:"")+`<a href="#premium" class="side-premium ${tab==="premium"?"on":""}">${icon("spark")}SLM Premium</a>`;
  $("#side").innerHTML=side;
  const av=$("#top-avatar");if(av)av.textContent=initial(typeof cloudUser!=="undefined"&&cloudUser?.email||S().gerant||"S");
  if(typeof billingHeaderHTML==="function")$("#top-premium").innerHTML=billingHeaderHTML();
}
const PAGE_EVENTS={home:"page_home",clients:"page_clients",client:"page_clients",plus:"page_plus",documents:"page_documents",premium:"page_billing",settings:"page_settings",data:"page_tools"};
function trackPage(){try{if(!usageOpened){usageOpened=true;cloudTrackUsageEvent("app_opened")}const ev=tab==="courses"?(coursesMode==="done"?"page_history":"page_courses"):tab==="finances"?(finTab==="invoices"?"page_factures":"page_compta"):PAGE_EVENTS[tab];if(ev&&ev!==lastTracked){lastTracked=ev;cloudTrackUsageEvent(ev)}}catch{}}
function go(keep){if(!db)return;const y=scrollY,prev=tab;[tab,routeParam]=parseRoute();navHTML();const v=$("#view");let html="";try{html=views[tab](routeParam)}catch(e){console.error(e);html=`<div class="page"><div class="empty">${icon("alert")}<b>Cette page n’a pas pu s’afficher</b><p>${esc(e.message||e)}</p><a class="btn" href="#home">Revenir à l’accueil</a></div></div>`}
  if(tab==="admin")html=`<div class="page"><div class="compat">${html}</div></div>`;
  v.innerHTML=html;const page=v.firstElementChild;
  if(!keep&&page){page.classList.add("enter");[...page.children].forEach((c,i)=>c.style.setProperty("--i",Math.min(i,8)));animateCounts(v)}
  const h=v.querySelector("h1,h2");const title=h?.textContent?.trim()||"SLM Transfert";$("#top-title").textContent=title;document.title=`${title} · SLM Transfert`;
  if(keep)scrollTo(0,y);else{scrollTo(0,0);if(prev!==tab)v.focus({preventScroll:true})}
  afterRender();trackPage();connectionStatus()}
const refresh=()=>go(true);
/* Navigation animée : l’ancienne vue s’efface (View Transitions), sinon rendu direct comme avant. */
function goAnimated(){if(!db||RM.matches||document.hidden||typeof document.startViewTransition!=="function")return go();try{document.startViewTransition(()=>go())}catch{go()}}
addEventListener("hashchange",()=>{if(mOpen){mOpen=false;$("#modal").classList.add("hidden");$("#modal").classList.remove("open");$("#modal").innerHTML="";document.body.classList.remove("nolock")}goAnimated()});
function afterRender(){document.querySelectorAll(".seg").forEach(segThumb);if(typeof billingAfterRender==="function")billingAfterRender()}
function segThumb(seg){const on=seg.querySelector('[aria-pressed="true"]');let th=seg.querySelector(".thumb");if(!on){th?.remove();return}if(!th){th=document.createElement("i");th.className="thumb";seg.prepend(th)}th.style.left=on.offsetLeft+"px";th.style.width=on.offsetWidth+"px"}
addEventListener("resize",debounce(()=>document.querySelectorAll(".seg").forEach(segThumb),120));

/* ════════════ Verrouillage, code, démarrage ════════════ */
const lockBrand=`<div class="brand" style="justify-content:center;font-size:30px">SLM<small>TRANSFERT</small></div>`;
function pinUI(msg){document.body.classList.add("locked");applyTheme();$("#lock").innerHTML=`<div class="auth"><div class="auth-main"><div class="pin">${lockBrand}<div style="text-align:center"><b style="font-size:17px">Entrez votre code</b><p class="muted" style="font-size:13.5px">${typeof cloudUser!=="undefined"&&cloudUser?.email?esc(cloudUser.email):"Code à 4 chiffres"}</p></div><div class="pin-dots" id="dots">${[0,1,2,3].map(i=>`<i class="${i<pinBuf.length?"on":""}"></i>`).join("")}</div><div class="keys">${[1,2,3,4,5,6,7,8,9].map(n=>`<button type="button" onclick="pinKey('${n}')">${n}</button>`).join("")}<span class="k-empty"></span><button type="button" onclick="pinKey('0')">0</button><button type="button" class="k-del" onclick="pinKey('x')" aria-label="Effacer">Effacer</button></div><div class="msg ${msg?"err":""}" ${msg?"":"hidden"} role="alert">${esc(msg||"")}</div>${typeof cloudUser!=="undefined"&&cloudUser?`<label class="switch remember"><span>Rester connecté sur cet appareil<small>Ne plus demander le code sur cet appareil</small></span><input type="checkbox" id="pin_remember" ><i></i></label><button class="btn ghost sm" onclick="cloudLogout()">Changer de compte</button>`:""}</div></div></div>`}
function setupPinUI(msg){document.body.classList.add("locked");$("#lock").innerHTML=`<div class="auth"><div class="auth-main"><div class="auth-box">${lockBrand}<div><h1>Votre code personnel</h1><p class="sub" style="margin-top:8px">4 chiffres pour ouvrir l’application sur cet appareil. Il ne remplace pas votre mot de passe.</p></div><div class="fields"><div class="field"><label for="pin-new">Nouveau code</label><input id="pin-new" type="password" inputmode="numeric" maxlength="4" pattern="[0-9]*" autocomplete="new-password"></div><div class="field"><label for="pin-confirm">Confirmer le code</label><input id="pin-confirm" type="password" inputmode="numeric" maxlength="4" pattern="[0-9]*" autocomplete="new-password" onkeydown="if(event.key==='Enter')createLocalPin()"></div></div>${msg?`<div class="msg err" role="alert">${esc(msg)}</div>`:""}<button class="btn lg block" onclick="createLocalPin()">Enregistrer et continuer</button></div></div></div>`;setTimeout(()=>$("#pin-new")?.focus(),60)}
async function createLocalPin(){const a=$("#pin-new").value,b=$("#pin-confirm").value;if(!/^\d{4}$/.test(a))return setupPinUI("Le code doit contenir exactement 4 chiffres.");if(a!==b)return setupPinUI("Les deux codes ne correspondent pas.");try{await saveLocalPin(a)}catch{return setupPinUI("Le navigateur n’a pas pu enregistrer le code.")}pinBuf="";await unlock()}
document.addEventListener("keydown",e=>{if(!document.body.classList.contains("locked")||!$("#dots"))return;if(/^\d$/.test(e.key))pinKey(e.key);else if(e.key==="Backspace")pinKey("x")});
function pinKey(k){if(!hasLocalPin())return setupPinUI("Créez votre code personnel pour continuer.");if(k==="x")pinBuf=pinBuf.slice(0,-1);else if(pinBuf.length<4)pinBuf+=k;document.querySelectorAll("#dots i").forEach((d,i)=>d.classList.toggle("on",i<pinBuf.length));if(pinBuf.length<4)return;
  let t={n:0,u:0};try{t=JSON.parse(localStorage.getItem(T_KEY)||'{"n":0,"u":0}')}catch{}
  if(Date.now()<t.u){pinBuf="";return pinUI(`Trop d’essais. Patientez ${Math.ceil((t.u-Date.now())/1000)} s.`)}
  if(pinBuf===getPin()){try{localStorage.removeItem(T_KEY)}catch{}if($("#pin_remember")?.checked&&typeof slmSetRemember==="function")slmSetRemember(true);pinBuf="";unlock()}else{t.n++;if(t.n>=5)t.u=Date.now()+30000;try{localStorage.setItem(T_KEY,JSON.stringify(t))}catch{}pinBuf="";const d=$("#dots");d?.classList.add("shake");navigator.vibrate?.(120);setTimeout(()=>pinUI("Code incorrect"),380)}}
async function unlock(){if(!db){try{db=pending?JSON.parse(pending):JSON.parse(JSON.stringify(def))}catch{db=JSON.parse(JSON.stringify(def))}fixDb()}
  try{if(typeof cloudPrepareAccount==="function"&&cloudUser)await cloudPrepareAccount()}catch{}
  document.body.classList.remove("locked");$("#lock").innerHTML="";applyTheme();hiddenAt=0;hideSplash();try{navigator.storage?.persist?.()}catch{}
  if(["#signup","#login",""].includes(location.hash))history.replaceState(history.state,"",location.pathname+location.search+"#home");
  go();checkReminders();save();try{cloudPull();adminCheckAccess?.();billingAppReady?.()}catch{}}
function lock(){db=null;pending=null;if(mOpen)close_();(async()=>{pending=await fetchStore(D_KEY);pinBuf="";pinUI()})()}
function migrateUI(err){document.body.classList.add("locked");$("#lock").innerHTML=`<div class="auth"><div class="auth-main"><div class="auth-box">${lockBrand}<h1>Récupérer vos données</h1><p class="sub">Saisissez une dernière fois votre ancien identifiant et mot de passe pour transférer les données de l’ancienne version.</p><div class="fields"><div class="field"><label for="mid">Ancien identifiant</label><input id="mid" autocapitalize="none" autocomplete="off"></div><div class="field"><label for="mpw">Ancien mot de passe</label><input id="mpw" type="password" autocomplete="off"></div></div>${err?`<div class="msg err">${esc(err)}</div>`:""}<button class="btn lg block" onclick="doMigrate()">Récupérer mes données</button><button class="btn ghost block" onclick="confirmTap(this,()=>{pending=null;pinBuf='';hasLocalPin()?pinUI():setupPinUI()},'Confirmer : repartir de zéro')">Repartir de zéro</button></div></div></div>`}
async function doMigrate(){try{const a=JSON.parse(await fetchStore(A_KEY)),e=JSON.parse(await fetchStore(E_KEY));if($("#mid").value.trim()!==a.id)throw 0;const k=await derive($("#mpw").value,unb64(e.s));const pt=await crypto.subtle.decrypt({name:"AES-GCM",iv:unb64(e.i)},k,unb64(e.d));pending=new TextDecoder().decode(pt);await store(D_KEY,pending);await store(A_KEY,null);await store(E_KEY,null);pinBuf="";if(!hasLocalPin())return setupPinUI("Données récupérées. Créez votre code personnel.");pinUI("Données récupérées. Entrez votre code.")}catch{migrateUI("Identifiant ou mot de passe incorrect")}}
async function boot(){await migrateLegacyPinForAccount();const d=await fetchStore(D_KEY),mustChoosePin=!!(typeof cloudUser!=="undefined"&&cloudUser?.id&&!hasLocalPin());
  if(typeof cloudUser!=="undefined"&&cloudUser?.id&&typeof deviceNoPin==="function"&&deviceNoPin()){if(d)pending=d;else{const a=await fetchStore(A_KEY),e=await fetchStore(E_KEY);if(a&&e&&window.crypto&&crypto.subtle)return migrateUI();try{const o=localStorage.getItem(OLD_KEY);if(o)pending=o}catch{}}return unlock()}
  if(d){pending=d;try{const x=JSON.parse(d);if(!mustChoosePin&&x.settings&&x.settings.pinOn===false){db=x;fixDb();return unlock()}}catch{}if(mustChoosePin||!hasLocalPin())return setupPinUI();return pinUI()}
  const a=await fetchStore(A_KEY),e=await fetchStore(E_KEY);if(a&&e&&window.crypto&&crypto.subtle)return migrateUI();
  try{const o=localStorage.getItem(OLD_KEY);if(o)pending=o}catch{}if(mustChoosePin||!hasLocalPin())return setupPinUI();pinUI()}
document.addEventListener("visibilitychange",()=>{if(document.hidden){hiddenAt=Date.now()}else{const m=db?+db.settings.lockMin:0;if(db&&db.settings.pinOn!==false&&!(typeof deviceNoPin==="function"&&deviceNoPin())&&m>0&&hiddenAt&&Date.now()-hiddenAt>m*60000)lock();else checkReminders();hiddenAt=0}});
function changePin(){modal(sheet({title:"Changer de code",body:`<div class="field"><label for="n1">Nouveau code (4 chiffres)</label><input id="n1" type="password" inputmode="numeric" maxlength="4" pattern="[0-9]*" autocomplete="off"></div>`,foot:`<button class="btn secondary" onclick="close_()">Annuler</button><button class="btn" onclick="doPin()">Enregistrer</button>`}))}
async function doPin(){const v=$("#n1").value;if(!/^\d{4}$/.test(v))return toast("Le code doit contenir 4 chiffres.");try{await saveLocalPin(v);close_();toast("Code modifié")}catch{toast("Impossible d’enregistrer le code")}}
async function resetAll(){for(const k of [D_KEY,A_KEY,E_KEY,T_KEY,PIN_KEY,activePinKey()])await store(k,null);location.reload()}

/* ════════════ Connexion / inscription ════════════ */
async function cloudAuthUI(mode="login",message=""){
  document.body.classList.add("locked");hideSplash();const signup=mode==="signup";
  $("#lock").innerHTML=`<div class="auth" id="cloud-auth-screen">
  <aside class="auth-art"><canvas id="auth-canvas" aria-hidden="true"></canvas><div class="brand" style="color:var(--night-ink)">SLM<small style="color:var(--night-mut)">TRANSFERT</small></div><div><h2>Vos courses, vos clients, <em>votre marge</em>.</h2><p>L’application des chauffeurs VTC et taxis indépendants. Agenda, factures en un geste, et la vraie rentabilité de chaque trajet.</p></div><p style="font-size:12.5px">Synchronisé sur téléphone et ordinateur · Factures PDF · Paiement sécurisé Stripe</p></aside>
  <div class="auth-main"><div class="auth-box">
    <div class="brand" style="font-size:28px">SLM<small>TRANSFERT</small></div>
    <div><h1>${signup?"Créer votre espace":"Bon retour"}</h1><p class="sub" style="margin-top:8px">${signup?"Gratuit, sans carte bancaire. Vos données se synchronisent sur tous vos appareils.":"Connectez-vous pour retrouver vos courses, votre agenda et vos factures."}</p></div>
    <div class="seg" role="group" aria-label="Choix"><button type="button" aria-pressed="${!signup}" onclick="cloudAuthSwitch('login')">Connexion</button><button type="button" aria-pressed="${signup}" onclick="cloudAuthSwitch('signup')">Inscription</button></div>
    <form class="fields" onsubmit="event.preventDefault();${signup?"cloudSignup()":"cloudLogin()"}">
      <div class="field"><label for="cl_mail">Adresse e-mail</label><input id="cl_mail" type="email" inputmode="email" autocomplete="username" placeholder="vous@exemple.fr" required></div>
      <div class="field"><label for="cl_pw">Mot de passe</label><input id="cl_pw" type="password" autocomplete="${signup?"new-password":"current-password"}" placeholder="${signup?"8 caractères minimum":"Votre mot de passe"}" required></div>
      ${signup?`<details class="terms"><summary>Lire les conditions d’utilisation</summary><div><p><b>Le service.</b> SLM Transfert aide les chauffeurs indépendants à organiser leur activité : courses, clients, agenda, factures, dépenses et documents.</p><p><b>Votre compte et vos données.</b> Vous êtes responsable de l’exactitude des informations saisies, de la confidentialité de vos identifiants et de l’usage licite des données de vos clients. Les fonctions d’export permettent de conserver une copie de vos données.</p><p><b>Outil d’aide à la gestion.</b> Les calculs, indicateurs et documents générés sont des outils d’assistance. Vérifiez montants, factures et obligations comptables ou fiscales avant de les utiliser.</p><p><b>Offre gratuite et Premium.</b> Les fonctions de chaque offre sont présentées dans l’application. Le prix, la périodicité, l’essai éventuel et les modalités de résiliation d’un abonnement sont affichés avant la confirmation du paiement par Stripe.</p><p><b>Disponibilité et sécurité.</b> L’accès peut être interrompu pour maintenance. Protégez votre appareil et votre mot de passe ; la synchronisation ne remplace pas une copie de sauvegarde personnelle.</p><p><b>Respect du service.</b> N’utilisez pas l’application pour une activité illégale, pour accéder aux données d’autrui ou perturber le service.</p><p><b>Confidentialité.</b> Le partage de statistiques d’utilisation fait l’objet d’un choix séparé, facultatif.</p><small>Version ${TERMS_VERSION}</small></div></details>
      <label class="consent"><input id="cl_terms" type="checkbox" required onchange="cloudSignupTermsChanged(this)"><span><b>J’accepte les conditions d’utilisation.</b> Obligatoire pour créer un compte.</span></label>
      <label class="consent"><input id="cl_analytics" type="checkbox"><span><b>Statistiques d’utilisation (facultatif).</b> Partager les rubriques consultées pour améliorer l’application. Aucun trajet, contact, montant ou facture n’est transmis. Modifiable à tout moment.</span></label>`:`<button type="button" class="link" style="justify-self:start;font-size:13.5px" onclick="cloudForgotPassword()">Mot de passe oublié ?</button>`}
      <label class="switch remember"><span>Rester connecté sur cet appareil<small>Plus besoin de vous reconnecter ni de saisir de code à chaque ouverture</small></span><input type="checkbox" id="cl_remember" checked><i></i></label>
      ${message?`<div class="msg ${/impossible|refusée|erreur/i.test(message)?"err":""}" role="status">${esc(message)}</div>`:""}
      ${!sb?`<div class="msg err">Le service de connexion est injoignable. Vérifiez votre connexion Internet.</div>`:""}
      <button ${signup?'id="cl_signup" disabled':""} class="btn lg block" type="submit">${signup?"Créer mon compte gratuit":"Se connecter"}</button>
    </form>
    <p class="faint" style="font-size:12.5px;text-align:center"><a href="landing.html">Découvrir SLM Transfert</a> · Premium dès ${typeof premiumPriceLabel==="function"?premiumPriceLabel("monthly"):"9,90 €"}/mois</p>
  </div></div></div>`;
  startAuthArt();
}
function startAuthArt(){const cv=$("#auth-canvas");if(!cv||!cv.getClientRects().length)return;const x=cv.getContext("2d");let w,h,t0=performance.now();const size=()=>{const r=cv.getBoundingClientRect();w=r.width;h=r.height;cv.width=w*devicePixelRatio;cv.height=h*devicePixelRatio;x.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)};size();addEventListener("resize",size);
  const P=t=>{const s=1-t;return[w*(.08*s*s*s+3*.35*t*s*s+3*.6*t*t*s+.95*t*t*t),h*(.85*s*s*s+3*.55*t*s*s+3*.75*t*t*s+.25*t*t*t)]};
  const draw=now=>{if(!cv.isConnected)return;const t=(now-t0)/1000;x.clearRect(0,0,w,h);x.fillStyle="rgba(227,245,235,.16)";for(let gx=0;gx<w;gx+=26)for(let gy=0;gy<h;gy+=26){x.fillRect(gx,gy+Math.sin(gx*.02+gy*.015)*3,1.2,1.2)}
    x.strokeStyle="rgba(255,255,255,.5)";x.lineWidth=2;x.setLineDash([3,9]);x.beginPath();for(let i=0;i<=120;i++){const[a,b]=P(i/120);i?x.lineTo(a,b):x.moveTo(a,b)}x.stroke();x.setLineDash([]);
    for(let i=0;i<14;i++){const u=((t*.06)+i/14)%1,[a,b]=P(u);const g=x.createRadialGradient(a,b,0,a,b,10);g.addColorStop(0,"rgba(255,255,255,.95)");g.addColorStop(1,"rgba(168,224,194,0)");x.fillStyle=g;x.beginPath();x.arc(a,b,10,0,7);x.fill()}
    if(!RM.matches)requestAnimationFrame(draw)};requestAnimationFrame(draw)}

/* ════════════ PDF & partage ════════════ */
async function pdfFile(id){const inv=db.factures.find(x=>x.id===id);const blob=await buildInvoicePdf(inv);return new File([blob],`${inv.statut==="devis"?"Devis":"Facture"}-${inv.num}.pdf`,{type:"application/pdf"})}
async function pdfShare(id){try{const r=await shareOrDownload(await pdfFile(id));if(r==="downloaded")toast("PDF enregistré dans vos téléchargements")}catch(e){toast("Le PDF n’a pas pu être créé")}}
async function pdfDown(id){try{const f=await pdfFile(id);dl(f.name,f,f.type);toast("PDF enregistré dans vos téléchargements")}catch{toast("Le PDF n’a pas pu être créé")}}

/* ════════════ ACCUEIL ════════════ */
function monthStats(ym){return stats(d=>!!d&&d.slice(0,7)===ym)}
function upcoming(){const now=Date.now()-90*6e4;return db.courses.filter(c=>c.statut==="planifiée"&&c.date&&rideAt(c).getTime()>=now).sort((a,b)=>rideAt(a)-rideAt(b))}
function greeting(){const h=new Date().getHours();return h<5?"Bonne nuit":h<12?"Bonjour":h<18?"Bon après-midi":"Bonsoir"}
function firstName(){const g=(S().gerant||"").trim().split(/\s+/)[0];return g||""}
function nextCardHTML(c){if(!c)return`<section class="next empty"><span class="eyebrow">Prochaine course</span><h2 class="serif" style="font-size:28px;margin:4px 0 6px">Rien de prévu pour l’instant</h2><p class="muted">Ajoutez une course : elle apparaîtra ici avec l’itinéraire et le client à appeler.</p><div class="btn-row" style="margin-top:14px"><button class="btn" onclick="editC()">${icon("plus")} Planifier une course</button></div></section>`;
  const t=tel(c);return`<section class="next" aria-label="Prochaine course"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><span class="lbl">PROCHAINE COURSE · ${esc(dayLabel(c.date).toUpperCase())}</span><span class="when">${icon("clock")} ${relTime(c)}</span></div>
  <div class="time" style="margin-top:10px">${esc(c.heure||"--:--")}</div>
  <div class="route"><span class="dot"></span><span>${esc(c.depart||"Départ à préciser")}</span><span class="line"></span><span></span><span class="dot fill"></span><span>${esc(c.arrivee||"Arrivée à préciser")}</span></div>
  <div class="meta"><span><b style="font-size:16px">${esc(clientName(c.client))}</b> <span style="opacity:.7">· ${esc(c.type||"Course")}</span></span><b>${eur(c.prix)}</b></div>
  <div class="acts">${c.depart?`<a class="primary" href="${appLink("waze",c.depart)}" target="_blank" rel="noopener">${icon("nav")} Itinéraire</a>`:""}${t?`<a href="tel:${esc(t)}">${icon("phone")} Appeler</a>`:""}<button onclick="doneC('${esc(c.id)}')">${icon("check")} Terminer</button><a href="#course/${esc(c.id)}">Détails</a></div></section>`}
function chartHTML(year){const vals=MOIS.map((_,i)=>monthStats(`${year}-${String(i+1).padStart(2,"0")}`).ca),mx=Math.max(...vals,1),cur=+thisMonth().slice(5,7)-1,W=600,H=170,pb=22,bw=W/12;
  const nice=mx<=0?1:Math.pow(10,Math.floor(Math.log10(mx)));const top=Math.ceil(mx/nice)*nice;
  let g="";[.5,1].forEach(f=>{const y=(H-pb)-(H-pb-8)*f;g+=`<line class="gridline" x1="0" x2="${W}" y1="${y}" y2="${y}"/><text class="axis" x="${W}" y="${y-4}" text-anchor="end">${money0(top*f)}</text>`});
  vals.forEach((v,i)=>{const h=Math.max(v>0?3:0,(H-pb-8)*v/top),x=i*bw+bw*.18,y=H-pb-h;g+=`<g><title>${MOIS[i]} : ${eur(v)}</title><rect class="col col-in ${String(year)===thisMonth().slice(0,4)&&i===cur?"cur":""}" x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${(bw*.64).toFixed(1)}" height="${h.toFixed(1)}" rx="5" style="animation-delay:${i*35}ms"/></g><text class="axis" x="${(i*bw+bw/2).toFixed(1)}" y="${H-5}" text-anchor="middle">${["Jan","Fév","Mar","Avr","Mai","Juin","Juil","Août","Sep","Oct","Nov","Déc"][i]}</text>`});
  return`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Chiffre d’affaires par mois en ${year}">${g}</svg>`}
function onboardingHTML(){const m=db.meta||{},hasData=["courses","clients","depenses","factures","docs"].some(k=>db[k]?.length);if(hasData||m.onboardingDismissed)return"";const s=S();
  const steps=[[!!db.courses.length,"Ajoutez votre première course","Elle remplit votre agenda et vos chiffres.","editC()"],[!!(s.siret||s.adresse),"Complétez votre entreprise","SIRET et adresse apparaissent sur vos factures.","location.hash='settings'"],[typeof pushDeviceActive==="function"&&pushDeviceActive(),"Activez les rappels","Une notification avant chaque course.","askNotif()"]];
  return`<section class="card"><div class="card-head"><div><span class="eyebrow">Bien démarrer</span><h3 style="font-size:18px">Trois réglages, deux minutes</h3></div><button class="btn ghost sm" onclick="dismissOnboarding()">Masquer</button></div><div class="list">${steps.map(([done,t,d,a])=>`<button class="item" onclick="${a}"><span class="ico ${done?"brand":""}">${icon(done?"check":"right")}</span><span><b>${t}</b><small>${d}</small></span>${icon("right","chev")}</button>`).join("")}</div></section>`}
function dismissOnboarding(){db.meta=db.meta||{};db.meta.onboardingDismissed=true;save();refresh()}
views.home=()=>{const s=S(),ym=thisMonth(),st=monthStats(ym),prevYm=shiftMonth(ym,-1),dayN=today().slice(8,10),prev=stats(d=>!!d&&d.slice(0,7)===prevYm&&d.slice(8,10)<=dayN),up=upcoming(),next=up[0],todayRest=up.filter(c=>c.date===today()).slice(1,4),unpaid=db.factures.filter(f=>f.statut==="en attente"),exp=db.docs.filter(d=>d.exp&&(new Date(d.exp)-new Date())/864e5<30),goal=Math.max(1,+s.objectif||0),pct=Math.min(100,Math.round(st.ca/goal*100)),delta=prev.ca?Math.round((st.ca-prev.ca)/prev.ca*100):null,name=firstName();
  return`<div class="page">
  <div class="hello"><div><span class="eyebrow">${esc(cap(new Date().toLocaleDateString("fr-FR",{weekday:"long",day:"numeric",month:"long"})))}</span><h1>${greeting()}${name?`, ${esc(name)}`:""}.</h1><p>${up.filter(c=>c.date===today()).length?`${plural(up.filter(c=>c.date===today()).length,"course")} au programme aujourd’hui.`:"Aucune course aujourd’hui pour le moment."}</p></div><button class="btn secondary" onclick="editC()">${icon("plus")} Nouvelle course</button></div>
  ${onboardingHTML()}
  <div class="grid-2"><div style="display:grid;gap:18px;align-content:start">${nextCardHTML(next)}
    ${todayRest.length?`<section><div class="section-title"><h2>Plus tard aujourd’hui</h2><a href="#courses">Tout voir</a></div><div class="day" style="margin-top:12px">${todayRest.map(rideCard).join("")}</div></section>`:""}
  </div><div style="display:grid;gap:18px;align-content:start">
    ${typeof billingHomeCardHTML==="function"?billingHomeCardHTML(st):""}
    ${exp.length?`<a class="banner warn" href="#documents"><span class="ico warn">${icon("alert")}</span><span class="grow"><b>${plural(exp.length,"document")} à renouveler</b><small>${esc(exp.map(d=>d.nom).slice(0,2).join(", "))}</small></span>${icon("right","chev")}</a>`:""}
    ${s.showUnpaid&&unpaid.length?`<a class="banner" href="#finances" onclick="finTab='invoices';invFilter='due'"><span class="ico gold">${icon("receipt")}</span><span class="grow"><b>${eur(sum(unpaid,f=>f.total))} à encaisser</b><small>${plural(unpaid.length,"facture")} en attente de paiement</small></span>${icon("right","chev")}</a>`:""}
  </div></div>
  <section><div class="section-title"><h2>${esc(cap(monthLabel(ym)))}</h2><a href="#finances">Finances</a></div></section>
  <div class="kpis stagger">
    <div class="kpi"><span>Chiffre d’affaires</span><b class="tnum" data-count="${Math.round(st.ca)}">${money0(st.ca)}</b>${delta!=null?`<span class="delta ${delta>=0?"up":"down"}">${delta>=0?"+":""}${delta} % vs même période de ${monthLabel(prevYm,{month:"long"})}</span>`:`<small>Ce mois-ci</small>`}</div>
    <div class="kpi"><span>Courses terminées</span><b class="tnum" data-count="${st.C.filter(c=>c.statut==="terminée").length}" data-fmt="int">${st.C.filter(c=>c.statut==="terminée").length}</b><small>${plural(st.n,"course")} au total ce mois</small></div>
    <div class="kpi"><span>Kilomètres</span><b class="tnum" data-count="${Math.round(st.km)}" data-fmt="km">${Math.round(st.km).toLocaleString("fr-FR")} km</b><small>${st.km?(st.ca/st.km).toFixed(2).replace(".",",")+" € / km":"Distance saisie"}</small></div>
    <div class="kpi"><span>Net estimé</span><b class="tnum ${st.net<0?"money-neg":""}" data-count="${Math.round(st.net)}">${money0(st.net)}</b><small>Après dépenses et cotisations</small></div>
  </div>
  <div class="grid-2">${s.showChart?`<section class="card"><div class="card-head"><h3>Chiffre d’affaires ${thisMonth().slice(0,4)}</h3><small>par mois</small></div>${chartHTML(thisMonth().slice(0,4))}</section>`:"<div></div>"}
  ${s.showObjectif?`<section class="card goal"><div class="ring" style="--p:${pct}"><b>${pct} %</b></div><div><span class="eyebrow">Objectif mensuel</span><b style="font-size:18px">${money0(st.ca)} sur ${money0(goal)}</b><p>${st.ca>=goal?"Objectif atteint ce mois-ci.":`Encore ${money0(goal-st.ca)} pour l’atteindre.`} <button class="link" onclick="location.hash='settings';setTimeout(()=>openSet('tar'),80)">Modifier</button></p></div></section>`:""}</div>
  </div>`};

/* ════════════ COURSES ════════════ */
function rideCard(c){const done=c.statut==="terminée",cancel=c.statut==="annulée",soon=!done&&!cancel&&rideAt(c)-new Date()<2*3600e3&&rideAt(c)>new Date();
  return`<a class="ride ${done?"done":""} ${cancel?"cancel":""} ${soon?"soon":""}" href="#course/${esc(c.id)}"><span class="stripe"></span><span class="t">${esc(c.heure||"--:--")}<small>${done?"Terminée":cancel?"Annulée":relTime(c)}</small></span><span style="min-width:0"><span class="who"><span>${esc(clientName(c.client))}</span>${c.type?`<span class="pill">${esc(c.type)}</span>`:""}</span><span class="rt">${esc(c.depart||"Départ ?")}<i>→</i>${esc(c.arrivee||"Arrivée ?")}</span></span><span class="p">${eur((+c.prix||0)+(done?(+c.pourboire||0):0))}<small>${c.km?num(c.km)+" km":esc(c.paiement||"")}</small></span></a>`}
function coursesRows(){const q=agendaNorm(coursesQ);let rows;
  if(coursesMode==="done")rows=db.courses.filter(c=>c.statut!=="planifiée").sort((a,b)=>rideAt(b)-rideAt(a));
  else{rows=db.courses.filter(c=>c.statut==="planifiée"&&c.date>=today());if(coursesMode==="today")rows=rows.filter(c=>c.date===today());if(coursesMode==="week")rows=rows.filter(c=>c.date<=dateIn(6));rows.sort((a,b)=>rideAt(a)-rideAt(b))}
  if(q)rows=rows.filter(c=>agendaNorm([clientName(c.client),c.type,c.depart,c.arrivee,c.notes,c.date,fd(c.date),c.heure,c.prix].join(" ")).includes(q));return rows}
function coursesListHTML(){const rows=coursesRows();if(!rows.length){const q=!!coursesQ;return`<div class="card flat"><div class="empty"><span class="ico">${icon(q?"search":coursesMode==="done"?"history":"cal")}</span><b>${q?`Aucun résultat pour « ${esc(coursesQ)} »`:coursesMode==="done"?"Aucune course terminée":coursesMode==="today"?"Rien aujourd’hui":"Aucune course à venir"}</b><p>${q?"Essayez un nom de client, une ville ou une date.":coursesMode==="done"?"Les courses terminées et annulées s’afficheront ici.":"Planifiez une course : elle apparaîtra ici, classée par jour."}</p>${q?`<button class="btn secondary" onclick="setCoursesQ('')">Effacer la recherche</button>`:coursesMode!=="done"?`<button class="btn" onclick="editC()">${icon("plus")} Nouvelle course</button>`:""}</div></div>`}
  const groups=new Map();const keyOf=c=>coursesMode==="done"?c.date.slice(0,7):c.date;rows.slice(0,300).forEach(c=>{const k=keyOf(c);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(c)});
  return[...groups.entries()].map(([k,list])=>`<section class="day"><div class="day-h"><h3>${coursesMode==="done"?esc(monthLabel(k)):esc(dayLabel(k))}</h3><small>${coursesMode==="done"?money0(sum(list.filter(c=>c.statut==="terminée"),c=>(+c.prix||0)+(+c.pourboire||0)))+" · ":""}${plural(list.length,"course")}</small></div>${list.map(rideCard).join("")}</section>`).join("")}
function setCoursesMode(m){coursesMode=m;history.replaceState(history.state,"","#courses");refresh()}
const setCoursesQ=v=>{coursesQ=v;const l=$("#courses-list");if(l)l.innerHTML=coursesListHTML();const x=$("#courses-q");if(x&&x.value!==v)x.value=v};
views.courses=()=>{const all=db.courses.filter(c=>c.statut==="planifiée"&&c.date>=today()),done=db.courses.filter(c=>c.statut!=="planifiée");const modes=[["upcoming","À venir",all.length],["today","Aujourd’hui",all.filter(c=>c.date===today()).length],["week","7 jours",all.filter(c=>c.date<=dateIn(6)).length],["done","Terminées",done.length]];
  return`<div class="page"><div class="head"><div><span class="eyebrow">Planning</span><h1>Courses</h1></div><div class="btn-row"><button class="btn secondary" onclick="icsAll()" ${all.length?"":"disabled"} title="Exporter vers votre agenda">${icon("cal")} Exporter</button><button class="btn" onclick="editC()">${icon("plus")} Nouvelle</button></div></div>
  <div class="chips scroll" role="group" aria-label="Filtrer">${modes.map(([k,l,n])=>`<button class="chip" aria-pressed="${coursesMode===k}" onclick="setCoursesMode('${k}')">${l} <b>${n}</b></button>`).join("")}</div>
  <div class="search">${icon("search")}<input id="courses-q" type="search" value="${esc(coursesQ)}" placeholder="Client, ville, date…" aria-label="Rechercher une course" oninput="setCoursesQ(this.value)"></div>
  <div id="courses-list" style="display:grid;gap:18px">${coursesListHTML()}</div></div>`};

views.course=id=>{const c=db.courses.find(x=>x.id===id);if(!c)return`<div class="page"><a class="crumb" href="#courses">${icon("left")} Courses</a><div class="card"><div class="empty"><b>Course introuvable</b><p>Elle a peut-être été supprimée sur un autre appareil.</p></div></div></div>`;
  const t=tel(c),fa=db.factures.find(x=>x.course===c.id),m=rideMargin(c),prem=typeof billingCanUsePremium==="function"&&billingCanUsePremium();const status=c.statut==="terminée"?`<span class="pill ok"><i></i>Terminée</span>`:c.statut==="annulée"?`<span class="pill danger"><i></i>Annulée</span>`:`<span class="pill brand"><i></i>${relTime(c)}</span>`;
  return`<div class="page"><a class="crumb" href="#courses">${icon("left")} Courses</a>
  <div class="head"><div><span class="eyebrow">${esc(dayLabel(c.date))} · ${esc(c.type||"Course")}</span><h1 class="tnum">${esc(c.heure||"--:--")}</h1></div><div class="btn-row">${status}</div></div>
  <div class="grid-2"><div style="display:grid;gap:16px;align-content:start">
    <section class="card detail-hero"><div class="route-big"><span class="dot"></span><span>${esc(c.depart||"Départ à préciser")}</span><span class="line"></span><span></span><span class="dot fill"></span><span>${esc(c.arrivee||"Arrivée à préciser")}</span></div>
    <div class="quick">${c.depart?`<a href="${appLink("waze",c.depart)}" target="_blank" rel="noopener">${icon("nav")}Waze</a><a href="${appLink("maps",c.depart)}" target="_blank" rel="noopener">${icon("pin")}Maps</a>`:""}${t?`<a href="tel:${esc(t)}">${icon("phone")}Appeler</a><a href="${waLink(c,c.statut==="planifiée"?msgConfirm(c):fill(S().msgArrive,VARS(c)))}" target="_blank" rel="noopener">${icon("msg")}${c.statut==="planifiée"?"Confirmer":"WhatsApp"}</a>`:""}<button onclick="icsOne('${esc(c.id)}')">${icon("cal")}Agenda</button></div></section>
    ${c.statut==="planifiée"?`<button class="btn lg block" onclick="doneC('${esc(c.id)}')">${icon("check")} Terminer la course</button>`:""}
    <section class="card"><div class="card-head"><h3>Client</h3><a class="link" style="font-size:13px" href="${c.client?`#client/${esc(c.client)}`:"#clients"}">Fiche client</a></div><div style="display:flex;gap:12px;align-items:center"><span class="avatar">${esc(initial(clientName(c.client)))}</span><div style="min-width:0"><b>${esc(clientName(c.client))}</b><small class="muted" style="display:block">${esc(cl(c.client).tel||"Pas de téléphone")}</small></div></div>${t&&c.statut==="planifiée"?`<div class="btn-row" style="margin-top:12px"><a class="btn soft sm" href="${waLink(c,fill(S().msgArrive,VARS(c)))}" target="_blank" rel="noopener">${icon("msg")} « Je suis arrivé »</a><a class="btn ghost sm" href="${smsLink(c,msgConfirm(c))}">${icon("mail")} Confirmer par SMS</a></div>`:""}</section>
    ${c.notes?`<section class="card"><h3 style="margin-bottom:6px">Notes</h3><p class="muted" style="white-space:pre-wrap">${esc(c.notes)}</p></section>`:""}
  </div><div style="display:grid;gap:16px;align-content:start">
    <section class="facts"><div><span>Prix TTC</span><b>${eur(c.prix)}</b></div><div><span>Paiement</span><b>${esc(c.paiement||"—")}</b></div><div><span>Distance</span><b>${c.km?num(c.km)+" km":"—"}</b></div><div><span>À vide</span><b>${c.kmVide?num(c.kmVide)+" km":"—"}</b></div><div><span>Pourboire</span><b>${eur(c.pourboire)}</b></div><div><span>Commission</span><b>${eur(c.commission)}</b></div></section>
    <section class="card"><div class="card-head"><h3>Ce qu’il vous reste</h3>${prem?`<span class="badge-premium">${icon("spark")} PREMIUM</span>`:`<span class="badge-premium">${icon("lock")} PREMIUM</span>`}</div>${breakdownHTML(c,prem)}${prem?"":`<button class="btn gold block" style="margin-top:14px" onclick="billingShowPremiumGate('course_profitability')">Voir ma marge sur chaque course</button>`}</section>
    <section class="card pad-0"><div class="list">${fa?`<button class="item" onclick="viewF('${esc(fa.id)}')"><span class="ico gold">${icon("receipt")}</span><span><b>Facture ${esc(fa.num)}</b><small>${esc(fa.statut)} · ${eur(fa.total)}</small></span>${icon("right","chev")}</button>`:`<button class="item" onclick="editF(null,'${esc(c.id)}')"><span class="ico">${icon("receipt")}</span><span><b>Créer une facture ou un devis</b><small>Pré-remplie avec cette course</small></span>${icon("right","chev")}</button>`}
    <button class="item" onclick="editC('${esc(c.id)}')"><span class="ico">${icon("edit")}</span><span><b>Modifier la course</b><small>Horaire, trajet, prix, statut</small></span>${icon("right","chev")}</button>
    <button class="item" onclick="duplicateC('${esc(c.id)}')"><span class="ico">${icon("copy")}</span><span><b>Dupliquer</b><small>Même trajet et client, nouvelle date</small></span>${icon("right","chev")}</button></div></section>
    <button class="btn ghost" onclick="askDelete('courses','${esc(c.id)}',this)">${icon("trash")} Supprimer la course</button>
  </div></div></div>`};
function breakdownHTML(c,prem){const m=rideMargin(c),max=Math.max(m.revenue,1),w=v=>Math.max(2,Math.min(100,v/max*100)).toFixed(1);const kmLabel=`${num(m.distance)} km × ${costKmValue().toFixed(2).replace(".",",")} €`;
  return`<div class="wf"><div class="wf-row"><span>Recette${c.pourboire?" + pourboire":""}</span><b>${eur(m.revenue)}</b><span class="track"><i style="left:0;width:100%"></i></span></div>
  <div class="wf-row neg"><span>Commission</span><b>− ${eur(m.commission)}</b><span class="track"><i style="left:0;width:${w(m.commission)}%"></i></span></div>
  <div class="wf-row neg"><span>${m.distance?kmLabel:"Kilomètres non saisis"}</span><b class="${prem?"":"locked-val"}">− ${eur(m.variable)}</b><span class="track"><i style="left:${w(m.commission)}%;width:${w(m.variable)}%"></i></span></div>
  <div class="wf-row res"><span><b>Il vous reste</b></span><b class="${prem?(m.margin<0?"money-neg":"money-pos"):"locked-val"}" style="font-size:17px">${eur(m.margin)}</b><span class="track"><i style="left:0;width:${w(Math.max(0,m.margin))}%;${prem?"":"filter:blur(3px)"}"></i></span></div></div>
  ${prem&&!(+S().costKm>0)?`<p class="note" style="margin-top:10px">Calcul avec 0,30 €/km par défaut. <button class="link" onclick="location.hash='settings';setTimeout(()=>openSet('tar'),80)">Réglez votre coût réel</button>.</p>`:""}`}
function doneC(id){finishCourse(db.courses.find(c=>c.id===id))}
function finishCourse(c){if(!c)return;c.statut="terminée";touch(c);let fa=db.factures.find(x=>x.course===c.id);
  if(!fa&&S().autoFacture&&c.prix>0){fa=touch({id:uid(),...nextNum(S().prefix),date:today(),client:c.client,desc:designOf(c),total:+c.prix,statut:(S().payesAuto||[]).includes(c.paiement)?"payée":"en attente",course:c.id});db.factures.push(fa)}
  save();go(true);if(fa&&S().autoPdf)pdfDown(fa.id).catch(()=>{});
  const t=tel(c),prem=typeof billingCanUsePremium==="function"&&billingCanUsePremium(),done=db.courses.filter(x=>x.statut==="terminée").length;
  if(!prem)billingTrackConversion?.("premium_promo_shown");
  modal(sheet({title:"",body:`<div style="display:grid;justify-items:center;text-align:center;gap:8px;padding-top:4px"><span class="halo" style="width:72px;height:72px;background:radial-gradient(circle,var(--brand-2),var(--brand));color:var(--brand-ink);box-shadow:0 0 0 10px var(--brand-soft)">${icon("check")}</span><h2 class="serif" style="font-size:30px">Course terminée</h2><p class="muted">${esc(clientName(c.client))} · ${eur((+c.prix||0)+(+c.pourboire||0))} encaissés${done%10===0?` · votre ${done}ᵉ course`:""}</p></div>
  <section class="card"><div class="card-head"><h3>Où part l’argent de cette course</h3>${prem?"":`<span class="badge-premium">${icon("lock")} PREMIUM</span>`}</div>${breakdownHTML(c,prem)}${prem?"":`<p class="note" style="margin-top:12px">Premium affiche ce qu’il vous reste sur chaque course, chaque client et chaque mois.</p><button class="btn gold block" style="margin-top:12px" onclick="close_();setTimeout(()=>billingShowPremiumGate('course_profitability'),320)">Voir ce qu’il me reste</button>`}</section>
  ${fa?`<section class="card pad-0"><div class="list"><div class="item"><span class="ico gold">${icon("receipt")}</span><span><b>Facture ${esc(fa.num)}</b><small>${fa.statut==="payée"?"Réglée":"À encaisser"} · ${eur(fa.total)}</small></span><span class="pill ${fa.statut==="payée"?"ok":"warn"}">${esc(fa.statut)}</span></div><button class="item" onclick="pdfShare('${esc(fa.id)}')"><span class="ico">${icon("share")}</span><span><b>Envoyer la facture</b><small>PDF prêt à partager</small></span>${icon("right","chev")}</button>${t?`<a class="item" href="${waLink(c,msgFact(c,fa))}" target="_blank" rel="noopener"><span class="ico">${icon("msg")}</span><span><b>Remercier par WhatsApp</b><small>Message avec le montant de la facture</small></span>${icon("right","chev")}</a>`:""}</div></section>`:""}`,foot:`<button class="btn secondary" onclick="close_()">Fermer</button>`}))}
function duplicateC(id){const c=db.courses.find(x=>x.id===id);if(!c)return;editC(null,{...c,id:undefined,date:today(),statut:"planifiée",pourboire:0})}

/* Formulaire de course */
let cfType="",cfPay="";
function editC(id,preset){const s=S();const base={date:today(),heure:"",statut:"planifiée",type:s.typeDef,paiement:s.payDef,prix:"",km:"",kmVide:0,pourboire:0,commission:0};const c=db.courses.find(x=>x.id===id)||Object.assign({},base,preset||{});cfType=c.type||s.typeDef;cfPay=c.paiement||s.payDef;
  const recents=[...db.clients].map(x=>({x,last:Math.max(0,...db.courses.filter(r=>r.client===x.id).map(r=>+r._updatedAt||0))})).sort((a,b)=>b.last-a.last).slice(0,6).map(r=>r.x);const cname=c.client?(cl(c.client).nom==="—"?"":cl(c.client).nom):"";const suggest=autoPriceValue(c.km);
  const body=`${id?"":voicePanelHTML()}
  <div class="fieldset"><span class="legend">${icon("clock")} Quand</span><div class="row-2"><div class="field"><label for="c_day">Jour</label><select id="c_day" onchange="setCDay(this.value)">${[["0","Aujourd’hui"],["1","Demain"],["2","Après-demain"],["x","Autre date"]].map(([v,l])=>`<option value="${v}" ${dayChoice(c.date)===v?"selected":""}>${l}</option>`).join("")}</select></div><div class="field"><label for="c_time">Heure</label><input id="c_time" type="time" value="${esc(c.heure||"")}"></div></div><div class="field"><label for="c_date">Date</label><input id="c_date" type="date" value="${esc(c.date)}" onchange="syncDateChips()"></div></div>
  <div class="fieldset"><span class="legend">${icon("user")} Client</span><div class="field"><label for="c_pick">Client</label><select id="c_pick" onchange="pickClientSel(this.value)"><option value="">Nouveau client…</option>${recents.length?`<optgroup label="Récents">${recents.map(x=>`<option value="${esc(x.id)}" ${c.client===x.id?"selected":""}>${esc(x.nom)}</option>`).join("")}</optgroup>`:""}${db.clients.filter(x=>!recents.includes(x)).length?`<optgroup label="Tous les clients">${db.clients.filter(x=>!recents.includes(x)).sort((a,b)=>String(a.nom).localeCompare(String(b.nom),"fr")).map(x=>`<option value="${esc(x.id)}" ${c.client===x.id?"selected":""}>${esc(x.nom)}</option>`).join("")}</optgroup>`:""}</select></div><div class="row-2"><div class="field" id="c_name_f" ${c.client&&db.clients.some(x=>x.id===c.client)?"hidden":""}><label for="c_client">Nom du nouveau client</label><input id="c_client" list="c_clients" autocomplete="off" value="${esc(cname)}" placeholder="Nom ou société" onchange="fillTelV8()"><datalist id="c_clients">${db.clients.map(x=>`<option value="${esc(x.nom)}">`).join("")}</datalist></div><div class="field"><label for="c_tel">Téléphone</label><input id="c_tel" type="tel" inputmode="tel" value="${esc(id?cl(c.client).tel||"":preset?.client?cl(c.client).tel||"":"")}" placeholder="06…"></div></div></div>
  <div class="fieldset"><span class="legend">${icon("pin")} Trajet</span><div class="field"><label for="c_dep">Départ</label><input id="c_dep" value="${esc(c.depart||"")}" placeholder="Adresse, gare, aéroport…" autocomplete="off"></div><div class="field"><label for="c_arr">Arrivée</label><input id="c_arr" value="${esc(c.arrivee||"")}" placeholder="Destination" autocomplete="off"></div><div class="row-2"><div class="field"><label for="c_km">Km avec client</label><div class="input-group"><input id="c_km" type="number" inputmode="decimal" step="any" min="0" value="${esc(c.km)}" oninput="autoPriceV8()"><span class="suffix">km</span></div></div><div class="field"><label for="c_kmv">Km à vide</label><div class="input-group"><input id="c_kmv" type="number" inputmode="decimal" step="any" min="0" value="${esc(c.kmVide||0)}"><span class="suffix">km</span></div></div></div></div>
  <div class="fieldset"><span class="legend">${icon("euro")} Tarif</span><div class="field"><label for="c_prix">Prix TTC</label><div class="input-group"><input id="c_prix" type="number" inputmode="decimal" step="0.01" min="0" value="${esc(c.prix)}" oninput="this.dataset.auto='0'" style="font-size:20px;font-weight:800"><span class="suffix">€</span></div><span class="hint" id="c_suggest">${suggest?`Tarif calculé : ${eur(suggest)}, appliqué si le prix est vide`:+s.tarifKm>0?"Saisissez les km pour calculer le tarif.":"Astuce : réglez votre tarif au km dans Paramètres pour un prix automatique."}</span></div>
    <div class="field"><label for="c_pay">Paiement</label><select id="c_pay" onchange="cfPay=this.value">${listWith(s.paiements,cfPay).map(p=>`<option value="${esc(p)}" ${p===cfPay?"selected":""}>${esc(p)}</option>`).join("")}</select></div>
    <div class="row-2"><div class="field"><label for="c_tip">Pourboire</label><div class="input-group"><input id="c_tip" type="number" inputmode="decimal" step="0.01" min="0" value="${esc(c.pourboire||0)}"><span class="suffix">€</span></div></div><div class="field"><label for="c_comm">Commission</label><div class="input-group"><input id="c_comm" type="number" inputmode="decimal" step="0.01" min="0" value="${esc(c.commission||0)}"><span class="suffix">€</span></div>${+s.commPct>0?`<span class="hint">Calculée automatiquement (${s.commPct} %) pour le type Plateforme si vide.</span>`:""}</div></div></div>
  <div class="fieldset"><span class="legend">${icon("info")} Détails</span><div class="field"><label for="c_type">Type de course</label><select id="c_type" onchange="cfType=this.value">${listWith(s.types,cfType).map(p=>`<option value="${esc(p)}" ${p===cfType?"selected":""}>${esc(p)}</option>`).join("")}</select></div>
    ${id?`<div class="field"><label for="c_status">Statut</label><select id="c_status">${["planifiée","terminée","annulée"].map(x=>`<option value="${x}" ${c.statut===x?"selected":""}>${cap(x)}</option>`).join("")}</select></div>`:""}
    <div class="field"><label for="c_notes">Notes</label><textarea id="c_notes" rows="2" placeholder="Numéro de vol, passagers, bagages…">${esc(c.notes||"")}</textarea></div></div>`;
  modal(sheet({title:id?"Modifier la course":"Nouvelle course",body,foot:`<button class="btn secondary" onclick="close_()">Annuler</button><button class="btn" onclick="saveC('${esc(id||"")}')">${id?"Enregistrer":"Planifier la course"}</button>`}));
  if(preset?.client)setTimeout(()=>{const t=$("#c_tel");if(t&&!t.value)t.value=cl(preset.client).tel||""},0)}
function pickChip(group,btn,kind){document.querySelectorAll(`#${group} .chip`).forEach(b=>b.setAttribute("aria-pressed",b===btn));if(kind==="type")cfType=btn.dataset.v;else cfPay=btn.dataset.v}
function pickSeg(btn){btn.parentElement.querySelectorAll("button").forEach(b=>b.setAttribute("aria-pressed",b===btn));segThumb(btn.parentElement)}
function setCDate(n){$("#c_date").value=dateIn(n);syncDateChips()}
/* Menus déroulants du formulaire de course */
const listWith=(list,v)=>v&&!list.includes(v)?[...list,v]:list;
const dayChoice=d=>d===dateIn(0)?"0":d===dateIn(1)?"1":d===dateIn(2)?"2":"x";
function setCDay(v){if(v!=="x")$("#c_date").value=dateIn(+v);else $("#c_date").focus();syncDateChips()}
function syncDateChips(){const v=$("#c_date")?.value,sel=$("#c_day");if(sel&&v)sel.value=dayChoice(v)}
function pickClientSel(id){const f=$("#c_name_f");if(id){pickClient(id);if(f)f.hidden=true;return}$("#c_client").value="";$("#c_tel").value="";if(f){f.hidden=false;$("#c_client").focus()}}
function pickClient(id){const c=db.clients.find(x=>x.id===id);if(!c)return;$("#c_client").value=c.nom;$("#c_tel").value=c.tel||"";const last=db.courses.filter(r=>r.client===id).sort((a,b)=>(+b._updatedAt||0)-(+a._updatedAt||0))[0];if(last&&!$("#c_dep").value){$("#c_dep").value=last.depart||"";$("#c_arr").value=last.arrivee||""}}
function fillTelV8(){const c=db.clients.find(x=>x.nom.toLowerCase()===$("#c_client").value.trim().toLowerCase());if(c&&c.tel&&!$("#c_tel").value)$("#c_tel").value=c.tel}
function swapRoute(){const a=$("#c_dep"),b=$("#c_arr");[a.value,b.value]=[b.value,a.value]}
function autoPriceValue(km){const s=S();km=+km;if(!(km>0)||!(+s.tarifKm>0||+s.tarifMin>0))return 0;return+Math.max(+s.tarifMin||0,(+s.tarifBase||0)+km*(+s.tarifKm||0)).toFixed(2)}
function autoPriceV8(){const v=autoPriceValue($("#c_km").value),p=$("#c_prix"),h=$("#c_suggest");if(h)h.textContent=v?`Tarif calculé : ${eur(v)}, appliqué si le prix est vide`:"";if(v&&(!p.value||p.dataset.auto==="1")){p.value=v.toFixed(2);p.dataset.auto="1"}}
function applySuggest(){const v=autoPriceValue($("#c_km").value);if(v){$("#c_prix").value=v.toFixed(2);$("#c_prix").dataset.auto="1"}}
function saveC(id){const g=k=>($("#"+k)?.value??"").trim();if(!g("c_date"))return toast("Choisissez une date.");
  const name=g("c_client");let cid="";if(name){let c=db.clients.find(x=>x.nom.toLowerCase()===name.toLowerCase());if(!c){c=touch({id:uid(),nom:name,type:"Particulier",tel:g("c_tel")});db.clients.push(c)}else if(!c.tel&&g("c_tel")){c.tel=g("c_tel");touch(c)}cid=c.id}
  const old=db.courses.find(x=>x.id===id);let comm=+g("c_comm");if(!comm&&cfType==="Plateforme"&&+S().commPct>0)comm=+(+g("c_prix")*S().commPct/100).toFixed(2);
  const statut=id?($("#c_status")?.value||old?.statut||"planifiée"):"planifiée";
  const o=Object.assign({},old||{},{id:id||uid(),date:g("c_date"),heure:g("c_time"),client:cid,depart:g("c_dep"),arrivee:g("c_arr"),prix:+g("c_prix"),km:+g("c_km"),kmVide:+g("c_kmv"),pourboire:+g("c_tip"),commission:comm,type:cfType,paiement:cfPay,statut,notes:$("#c_notes").value});
  if(id)Object.keys(db.notified).filter(k=>k.startsWith(id)).forEach(k=>delete db.notified[k]);
  touch(o);db.deleted=(db.deleted||[]).filter(x=>!(x.arr==="courses"&&x.id===o.id));const i=db.courses.findIndex(x=>x.id===o.id);i>=0?db.courses[i]=o:db.courses.push(o);save();if(!id)cloudTrackUsageEvent("course_created");close_();
  setTimeout(()=>{if(o.statut==="terminée"&&(!old||old.statut!=="terminée"))finishCourse(o);else if(!old&&o.statut==="planifiée"){go(true);afterSave(o)}else{go(true);toast("Course enregistrée")}checkReminders()},RM.matches?0:320)}
function afterSave(c){const t=tel(c);modal(sheet({title:"",body:`<div style="display:grid;justify-items:center;text-align:center;gap:6px"><span class="halo" style="width:64px;height:64px;background:radial-gradient(circle,var(--brand-2),var(--brand));color:var(--brand-ink);box-shadow:0 0 0 10px var(--brand-soft)">${icon("check")}</span><h2 class="serif" style="font-size:28px">Course planifiée</h2><p class="muted">${esc(dayLabel(c.date))} à ${esc(c.heure||"heure à préciser")} · ${esc(clientName(c.client))} · ${eur(c.prix)}</p>${S().rappelsOn&&offs().length?`<span class="pill brand">${icon("bell")} Rappels ${offs().map(labM).join(", ")} avant</span>`:""}</div>
  <section class="card pad-0"><div class="list">${t?`<a class="item" href="${waLink(c,msgConfirm(c))}" target="_blank" rel="noopener"><span class="ico brand">${icon("msg")}</span><span><b>Confirmer au client sur WhatsApp</b><small>Message prêt avec date, heure et prix</small></span>${icon("right","chev")}</a><a class="item" href="${smsLink(c,msgConfirm(c))}"><span class="ico">${icon("mail")}</span><span><b>Confirmer par SMS</b><small>Même message, par SMS</small></span>${icon("right","chev")}</a>`:""}<button class="item" onclick="icsOne('${esc(c.id)}')"><span class="ico">${icon("cal")}</span><span><b>Ajouter à mon agenda</b><small>Fichier .ics avec rappels</small></span>${icon("right","chev")}</button>${typeof pushDeviceActive==="function"&&!pushDeviceActive()&&S().rappelsOn?`<button class="item" onclick="askNotif()"><span class="ico warn">${icon("bell")}</span><span><b>Activer les rappels sur ce téléphone</b><small>Même quand l’application est fermée</small></span>${icon("right","chev")}</button>`:""}</div></section>`,foot:`<button class="btn secondary" onclick="close_()">Fermer</button><a class="btn" href="#course/${esc(c.id)}">Voir la course</a>`}))}
/* Dictée (Premium) */
function voicePanelHTML(){const ok=typeof billingCanUsePremium==="function"&&billingCanUsePremium();if(!ok)return`<button type="button" class="locked-feature" onclick="billingShowPremiumGate('voice_course')"><span class="ico gold">${icon("mic")}</span><span><b>Dictez la course</b><small>« Demain 14h30, aéroport de Genève vers Annecy, 85 euros » : le formulaire se remplit.</small></span><span class="badge-premium">${icon("lock")} PREMIUM</span></button>`;
  return`<section class="voice"><div class="top"><div><b>Dictez la course</b><small class="muted" style="display:block;font-size:12.5px">Décrivez le trajet en une phrase, puis vérifiez.</small></div><button type="button" class="btn sm" id="voice-ride-start" onclick="toggleVoiceRideCapture()">${icon("mic")} Dicter</button></div><div class="field"><textarea id="voice-ride-text" rows="2" aria-label="Phrase décrivant la course" placeholder="Demain à 14h30, de l’aéroport de Genève à Annecy, 85 euros, client Martin"></textarea></div><div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap"><small id="voice-ride-status" role="status" class="muted" style="font-size:12.5px">Dictez ou tapez votre phrase.</small><button type="button" class="btn soft sm" onclick="parseVoiceRideIntoForm()">Remplir le formulaire</button></div></section>`}
function parseVoiceRideIntoForm(){if(typeof billingRequirePremium==="function"&&!billingRequirePremium("voice_course"))return;const text=$("#voice-ride-text")?.value?.trim()||"";if(!text)return voiceRideStatus("Dictez ou saisissez une phrase d’abord.","error");
  const d=voiceParseRidePhrase(text),map=[["c_date",d.date],["c_time",d.heure],["c_client",d.client],["c_dep",d.depart],["c_arr",d.arrivee],["c_prix",d.prix],["c_km",d.km],["c_kmv",d.kmVide]];let n=0;
  for(const[k,v]of map){const el=$("#"+k);if(el&&v!==undefined&&v!==""){el.value=v;el.dispatchEvent(new Event("input",{bubbles:true}));el.dispatchEvent(new Event("change",{bubbles:true}));n++}}
  if(d.type){const sel=$("#c_type"),o=sel&&[...sel.options].find(x=>x.value.toLowerCase()===d.type.toLowerCase());if(o){sel.value=o.value;cfType=o.value;n++}}
  if(d.client){const pick=$("#c_pick"),o=pick&&[...pick.options].find(x=>x.value&&x.textContent.trim().toLowerCase()===String(d.client).trim().toLowerCase());if(o){pick.value=o.value;pickClientSel(o.value)}}syncDateChips();
  voiceRideStatus(n?`${n} information${n>1?"s":""} reconnue${n>1?"s":""}. Vérifiez puis enregistrez.`:"Je n’ai pas reconnu les champs. Précisez départ, arrivée, date et heure.",n?"ok":"error")}
function voiceRideStartLabel(listening){const b=$("#voice-ride-start");if(b)b.innerHTML=`${icon(listening?"x":"mic")} ${listening?"Arrêter":"Dicter"}`}

/* ════════════ CLIENTS ════════════ */
function clientAgg(id){const rows=db.courses.filter(x=>x.client===id&&x.statut!=="annulée");const done=rows.filter(x=>x.statut==="terminée");return{n:rows.length,ca:sum(rows,x=>x.prix),last:rows.map(x=>x.date).sort().pop()||"",done}}
function clientsListHTML(){const q=agendaNorm(clientsQ);const list=db.clients.map(c=>({c,a:clientAgg(c.id)})).filter(({c})=>!q||agendaNorm([c.nom,c.tel,c.email,c.type].join(" ")).includes(q)).sort((a,b)=>b.a.ca-a.a.ca);
  return list.length?`<section class="card pad-0"><div class="list">${list.map(({c,a})=>`<a class="item" href="#client/${esc(c.id)}"><span class="avatar">${esc(initial(c.nom))}</span><span><b>${esc(c.nom)}</b><small>${esc([c.type,c.tel].filter(Boolean).join(" · ")||"Aucun contact")}</small></span><span class="end"><b>${money0(a.ca)}</b><small>${plural(a.n,"course")}</small></span></a>`).join("")}</div></section>`:`<div class="card flat"><div class="empty"><span class="ico">${icon("users")}</span><b>${q?"Aucun client trouvé":"Votre carnet est vide"}</b><p>${q?"Vérifiez l’orthographe ou cherchez par téléphone.":"Les clients se créent automatiquement quand vous saisissez une course."}</p></div></div>`}
views.clients=()=>`<div class="page"><div class="head"><div><span class="eyebrow">Carnet</span><h1>Clients</h1><p>${plural(db.clients.length,"client")} · classés par chiffre d’affaires</p></div><button class="btn" onclick="editCl()">${icon("plus")} Nouveau client</button></div>
  <div class="search">${icon("search")}<input type="search" value="${esc(clientsQ)}" placeholder="Nom, téléphone, e-mail…" aria-label="Rechercher un client" oninput="clientsQ=this.value;const l=document.getElementById('clients-list');if(l)l.innerHTML=clientsListHTML()"></div>
  <div id="clients-list">${clientsListHTML()}</div></div>`;
views.client=id=>{const c=db.clients.find(x=>x.id===id);if(!c)return`<div class="page"><a class="crumb" href="#clients">${icon("left")} Clients</a><div class="card"><div class="empty"><b>Client introuvable</b></div></div></div>`;const a=clientAgg(id),rides=db.courses.filter(x=>x.client===id).sort((x,y)=>rideAt(y)-rideAt(x)),t=(c.tel||"").replace(/[\s.\-]/g,""),prem=typeof billingCanUsePremium==="function"&&billingCanUsePremium(),mg=sum(a.done,x=>rideMargin(x).margin);
  return`<div class="page"><a class="crumb" href="#clients">${icon("left")} Clients</a>
  <div class="head"><div style="display:flex;gap:14px;align-items:center"><span class="avatar" style="width:56px;height:56px;font-size:22px">${esc(initial(c.nom))}</span><div><span class="eyebrow">${esc(c.type||"Client")}</span><h1>${esc(c.nom)}</h1></div></div><div class="btn-row"><button class="btn secondary" onclick="editCl('${esc(c.id)}')">${icon("edit")} Modifier</button><button class="btn" onclick="editC(null,{client:'${esc(c.id)}'})">${icon("plus")} Course</button></div></div>
  <div class="quick">${t?`<a href="tel:${esc(t)}">${icon("phone")}Appeler</a><a href="https://wa.me/${intl(t)}" target="_blank" rel="noopener">${icon("msg")}WhatsApp</a><a href="sms:${esc(t)}">${icon("mail")}SMS</a>`:""}${c.email?`<a href="mailto:${esc(c.email)}">${icon("mail")}E-mail</a>`:""}</div>
  <div class="kpis"><div class="kpi"><span>Chiffre d’affaires</span><b>${money0(a.ca)}</b></div><div class="kpi"><span>Courses</span><b>${a.n}</b></div><div class="kpi"><span>Dernière course</span><b style="font-size:22px">${a.last?fd(a.last):"—"}</b></div><div class="kpi"><span>Marge cumulée</span><b class="${prem?"":"locked-val"}">${money0(mg)}</b>${prem?`<small>${plural(a.done.length,"course terminée","courses terminées")}</small>`:`<button class="link" style="font-size:12.5px;text-align:left" onclick="billingShowPremiumGate('client_profitability')">Débloquer avec Premium</button>`}</div></div>
  ${c.adresse||c.siret||c.email?`<section class="card"><div class="kv">${c.email?`<div><span>E-mail</span><b>${esc(c.email)}</b></div>`:""}${c.adresse?`<div><span>Adresse</span><b>${esc(c.adresse)}</b></div>`:""}${c.siret?`<div><span>SIRET</span><b>${esc(c.siret)}</b></div>`:""}</div></section>`:""}
  <section><div class="section-title"><h2>Historique</h2></div><div class="day" style="margin-top:12px">${rides.slice(0,50).map(rideCard).join("")||`<div class="card flat"><div class="empty"><b>Aucune course</b></div></div>`}</div></section>
  <button class="btn ghost" onclick="askDelete('clients','${esc(c.id)}',this)">${icon("trash")} Supprimer ce client</button></div>`};
function editCl(id){const c=db.clients.find(x=>x.id===id)||{type:"Particulier"};modal(sheet({title:id?"Modifier le client":"Nouveau client",body:`<div class="fields"><div class="field"><label for="k_nom">Nom ou société</label><input id="k_nom" value="${esc(c.nom||"")}"></div><div class="field"><label for="k_type">Type de client</label><select id="k_type">${listWith(["Particulier","Entreprise","Hôtel","Agence"],c.type).map(x=>`<option value="${esc(x)}" ${c.type===x?"selected":""}>${esc(x)}</option>`).join("")}</select></div><div class="row-2"><div class="field"><label for="k_tel">Téléphone</label><input id="k_tel" type="tel" inputmode="tel" value="${esc(c.tel||"")}"></div><div class="field"><label for="k_mail">E-mail</label><input id="k_mail" type="email" inputmode="email" value="${esc(c.email||"")}"></div></div><div class="field"><label for="k_adr">Adresse de facturation</label><input id="k_adr" value="${esc(c.adresse||"")}"></div><div class="field"><label for="k_siret">SIRET</label><input id="k_siret" inputmode="numeric" value="${esc(c.siret||"")}"></div></div>`,foot:`<button class="btn secondary" onclick="close_()">Annuler</button><button class="btn" onclick="saveCl('${esc(id||"")}')">Enregistrer</button>`}))}
function saveCl(id){const g=k=>$("#"+k).value.trim();if(!g("k_nom"))return toast("Le nom est obligatoire.");const old=db.clients.find(x=>x.id===id)||{};upsert("clients",Object.assign({},old,{id:id||uid(),nom:g("k_nom"),type:$("#k_type")?.value||"Particulier",tel:g("k_tel"),email:g("k_mail"),adresse:g("k_adr"),siret:g("k_siret")}));if(!id)cloudTrackUsageEvent("client_created");toast("Client enregistré")}

/* ════════════ FINANCES ════════════ */
function finPred(){if(finScope==="all")return()=>true;return finScope==="year"?d=>!!d&&d.slice(0,4)===finMonth.slice(0,4):d=>!!d&&d.slice(0,7)===finMonth}
function finLabel(){return finScope==="year"?`Année ${finMonth.slice(0,4)}`:cap(monthLabel(finMonth))}
function finShift(n){finMonth=finScope==="year"?shiftMonth(finMonth,12*n):shiftMonth(finMonth,n);refresh()}
function setFin(k,v){if(k==="tab")finTab=v;if(k==="scope")finScope=v;if(k==="inv")invFilter=v;history.replaceState(history.state,"","#finances");refresh()}
function hbarsHTML(obj,empty){const e=Object.entries(obj).sort((a,b)=>b[1]-a[1]);if(!e.length)return`<p class="note">${empty}</p>`;const mx=Math.max(...e.map(x=>x[1]),1);return`<div class="hbars">${e.slice(0,8).map(([k,v])=>`<div class="hbar"><span>${esc(k)}</span><b>${eur(v)}</b><span class="bar"><i style="width:${(v/mx*100).toFixed(1)}%"></i></span></div>`).join("")}</div>`}
views.finances=()=>{const st=stats(finPred()),o=S(),tabs=[["overview","Vue d’ensemble"],["invoices","Factures"],["expenses","Dépenses"]];
  let inner="";
  if(finTab==="overview"){const cats={},types={},tops={};st.D.forEach(d=>cats[d.cat]=(cats[d.cat]||0)+ +d.montant);st.C.forEach(c=>{types[c.type||"Autre"]=(types[c.type||"Autre"]||0)+ +c.prix;const n=clientName(c.client);tops[n]=(tops[n]||0)+ +c.prix});
    inner=`<div class="kpis stagger"><div class="kpi"><span>Recettes TTC</span><b data-count="${Math.round(st.ca)}">${money0(st.ca)}</b><small>${plural(st.n,"course")}</small></div><div class="kpi"><span>Dépenses</span><b data-count="${Math.round(st.dep)}">${money0(st.dep)}</b><small>${plural(st.D.length,"dépense")}</small></div><div class="kpi"><span>Net estimé</span><b class="${st.net<0?"money-neg":""}" data-count="${Math.round(st.net)}">${money0(st.net)}</b><small>Après dépenses et cotisations</small></div><div class="kpi"><span>Distance</span><b data-count="${Math.round(st.km)}" data-fmt="km">${Math.round(st.km).toLocaleString("fr-FR")} km</b><small>${st.km?(st.ca/st.km).toFixed(2).replace(".",",")+" € / km":"—"}</small></div></div>
    ${typeof billingFinanceCardHTML==="function"?billingFinanceCardHTML(st):""}
    <div class="grid-2 even"><section class="card"><div class="card-head"><h3>Taxes et cotisations</h3><small>estimations</small></div><div class="kv"><div><span>TVA collectée ${o.tvaOn?`(${o.tva} %)`:"(franchise)"}</span><b>${eur(st.tvaC)}</b></div><div><span>TVA déductible</span><b>${eur(st.tvaD)}</b></div><div><span>TVA à reverser</span><b>${eur(Math.max(0,st.tvaC-st.tvaD))}</b></div><div><span>${esc(st.social.label)}</span><b>${eur(st.cot)}</b></div></div><p class="note" style="margin-top:10px">${esc(st.social.note)}</p></section>
    <section class="card"><div class="card-head"><h3>Dépenses par catégorie</h3></div>${hbarsHTML(cats,"Aucune dépense sur la période.")}</section>
    <section class="card"><div class="card-head"><h3>Recettes par type</h3></div>${hbarsHTML(types,"Aucune recette sur la période.")}</section>
    <section class="card"><div class="card-head"><h3>Meilleurs clients</h3></div>${hbarsHTML(tops,"Aucun client sur la période.")}</section></div>
    <section class="card pad-0"><div class="list"><button class="item" onclick="xlsxOutV8()"><span class="ico brand">${icon("down")}</span><span><b>Exporter la période en Excel</b><small>Courses, clients, factures et dépenses de « ${esc(finLabel())} »</small></span>${icon("right","chev")}</button><button class="item" onclick="exportAppExcel(false)"><span class="ico">${icon("down")}</span><span><b>Exporter toute l’activité</b><small>Classeur complet, restaurable</small></span>${icon("right","chev")}</button></div></section>`}
  else if(finTab==="invoices"){const P=finPred(),all=db.factures.filter(f=>P(f.date)),fl=[["all","Toutes",all],["due","À encaisser",all.filter(f=>f.statut==="en attente")],["paid","Payées",all.filter(f=>f.statut==="payée")],["quote","Devis",all.filter(f=>f.statut==="devis")]];const cur=(fl.find(x=>x[0]===invFilter)||fl[0])[2].slice().sort((a,b)=>(b.date||"").localeCompare(a.date||"")||(b.seq||0)-(a.seq||0));const due=db.factures.filter(f=>f.statut==="en attente");
    inner=`${due.length?`<div class="banner warn"><span class="ico warn">${icon("receipt")}</span><span class="grow"><b>${eur(sum(due,f=>f.total))} à encaisser au total</b><small>${plural(due.length,"facture")} en attente, toutes périodes</small></span><button class="btn sm secondary" onclick="finScope='all';setFin('inv','due')">Voir</button></div>`:""}
    <div class="chips scroll">${fl.map(([k,l,a])=>`<button class="chip" aria-pressed="${invFilter===k}" onclick="setFin('inv','${k}')">${l} <b>${a.length}</b></button>`).join("")}</div>
    ${cur.length?`<section class="card pad-0"><div class="list">${cur.map(f=>`<button class="item" onclick="viewF('${esc(f.id)}')"><span class="ico ${f.statut==="payée"?"brand":f.statut==="devis"?"":"warn"}">${icon(f.statut==="devis"?"file":"receipt")}</span><span><b>${esc(f.num)} · ${esc(clientName(f.client))}</b><small>${fd(f.date)} · ${esc(f.desc||"")}</small></span><span class="end"><b>${eur(f.total)}</b><span class="pill ${f.statut==="payée"?"ok":f.statut==="devis"?"":"warn"}">${esc(f.statut)}</span></span></button>`).join("")}</div></section>`:`<div class="card flat"><div class="empty"><span class="ico">${icon("receipt")}</span><b>Aucun document</b><p>Les factures se créent automatiquement en terminant une course${S().autoFacture?"":" (option désactivée dans Paramètres)"}.</p><button class="btn" onclick="editF()">${icon("plus")} Facture ou devis</button></div></div>`}`}
  else{const rows=st.D.slice().sort((a,b)=>b.date.localeCompare(a.date));inner=`${rows.length?`<section class="card pad-0"><div class="list">${rows.map(d=>`<button class="item" onclick="editD('${esc(d.id)}')"><span class="ico">${icon(d.receiptDataUrl?"camera":"wallet")}</span><span><b>${esc(d.desc||d.cat)}</b><small>${fd(d.date)} · ${esc(d.cat)}${d.receiptDataUrl?" · justificatif":""}</small></span><span class="end"><b>${eur(d.montant)}</b>${+d.tva?`<small>TVA ${eur(d.tva)}</small>`:""}</span></button>`).join("")}</div></section>`:`<div class="card flat"><div class="empty"><span class="ico">${icon("wallet")}</span><b>Aucune dépense sur la période</b><p>Carburant, péages, entretien : saisissez-les pour obtenir votre net réel.</p><button class="btn" onclick="editD()">${icon("plus")} Ajouter une dépense</button></div></div>`}`}
  const add=finTab==="expenses"?`<button class="btn" onclick="editD()">${icon("plus")} Dépense</button>`:finTab==="invoices"?`<button class="btn" onclick="editF()">${icon("plus")} Facture / devis</button>`:`<button class="btn secondary" onclick="editD()">${icon("plus")} Dépense</button>`;
  return`<div class="page"><div class="head"><div><span class="eyebrow">Suivi financier</span><h1>Finances</h1></div>${add}</div>
  <div class="seg" role="tablist">${tabs.map(([k,l])=>`<button role="tab" aria-pressed="${finTab===k}" onclick="setFin('tab','${k}')">${l}</button>`).join("")}</div>
  <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;justify-content:space-between">${finScope==="all"?`<b>Toutes les périodes</b>`:`<div class="period"><button class="btn ghost icon" onclick="finShift(-1)" aria-label="Période précédente">${icon("left")}</button><b>${esc(finLabel())}</b><button class="btn ghost icon" onclick="finShift(1)" aria-label="Période suivante">${icon("right")}</button></div>`}<div class="chips">${[["month","Mois"],["year","Année"],...(finTab==="invoices"?[["all","Tout"]]:[])].map(([k,l])=>`<button class="chip" aria-pressed="${finScope===k}" onclick="setFin('scope','${k}')">${l}</button>`).join("")}</div></div>
  ${inner}</div>`};
async function xlsxOutV8(){await xlsxOut(true,false)}
var inPer=d=>finPred()(d);
/* Dépenses */
function expenseReceiptPreviewHTML(url,name){if(!url)return"";return`<div class="receipt"><img src="${esc(url)}" alt="Justificatif ${esc(name||"")}"><span><b>Justificatif ajouté</b><small class="muted" style="display:block;font-size:12px">${esc(name||"Photo compressée")}</small></span><button type="button" class="btn ghost sm" onclick="expenseReceiptRemove()">Retirer</button></div>`}
function expenseReceiptRefreshPreview(){const a=$("#expense-receipt-preview");if(!a)return;const e=db?.depenses?.find(x=>x.id===expenseEditingId);const url=expenseReceiptRemoved?"":pendingExpenseReceipt?.dataUrl||expenseReceiptSafeUrl(e?.receiptDataUrl);a.innerHTML=expenseReceiptPreviewHTML(url,pendingExpenseReceipt?.name||e?.receiptName||"Justificatif")}
function expenseReceiptEditorHTML(e){const ok=typeof billingCanUsePremium==="function"&&billingCanUsePremium();if(!ok)return`<button type="button" class="locked-feature" onclick="billingShowPremiumGate('expense_receipt')"><span class="ico gold">${icon("camera")}</span><span><b>Photographiez le ticket</b><small>Le justificatif reste attaché à la dépense, sur tous vos appareils.</small></span><span class="badge-premium">${icon("lock")} PREMIUM</span></button>`;const url=expenseReceiptSafeUrl(e?.receiptDataUrl);return`<div class="field"><span class="label">Justificatif</span><label class="file-pick">${icon("camera")} Prendre une photo ou choisir une image<input id="expense-receipt-input" type="file" accept="image/*" capture="environment" onchange="expenseReceiptSelected(this)"></label><div id="expense-receipt-preview">${expenseReceiptPreviewHTML(url,e?.receiptName)}</div></div>`}
function editD(id){const d=db.depenses.find(x=>x.id===id)||{date:today(),cat:S().cats[0],montant:"",tva:0};pendingExpenseReceipt=null;expenseReceiptRemoved=false;expenseEditingId=id||"";window._dcat=d.cat;
  modal(sheet({title:id?"Modifier la dépense":"Nouvelle dépense",body:`<div class="fields"><div class="field"><label for="d_m">Montant TTC</label><div class="input-group"><input id="d_m" type="number" inputmode="decimal" step="0.01" min="0" value="${esc(d.montant)}" style="font-size:22px;font-weight:800"><span class="suffix">€</span></div></div><div class="field"><span class="label">Catégorie</span><div class="chips" id="d_cat">${S().cats.map(c=>`<button type="button" class="chip" aria-pressed="${c===d.cat}" data-v="${esc(c)}" onclick="document.querySelectorAll('#d_cat .chip').forEach(b=>b.setAttribute('aria-pressed',b===this));window._dcat=this.dataset.v">${esc(c)}</button>`).join("")}</div></div><div class="row-2"><div class="field"><label for="d_date">Date</label><input id="d_date" type="date" value="${esc(d.date)}"></div><div class="field"><label for="d_tva">dont TVA</label><div class="input-group"><input id="d_tva" type="number" inputmode="decimal" step="0.01" min="0" value="${esc(d.tva||0)}"><span class="suffix">€</span></div></div></div><div class="field"><label for="d_desc">Description</label><input id="d_desc" value="${esc(d.desc||"")}" placeholder="Ex. plein Total A41"></div>${expenseReceiptEditorHTML(d)}${id?`<button class="btn ghost" onclick="askDelete('depenses','${esc(id)}',this)">${icon("trash")} Supprimer</button>`:""}</div>`,foot:`<button class="btn secondary" onclick="close_()">Annuler</button><button class="btn" onclick="saveD('${esc(id||"")}')">Enregistrer</button>`}))}
function saveD(id){const prev=db.depenses.find(x=>x.id===id);if(pendingExpenseReceipt&&typeof billingRequirePremium==="function"&&!billingRequirePremium("expense_receipt"))return;if(!$("#d_date").value)return toast("Choisissez une date.");if(!(+$("#d_m").value>0))return toast("Saisissez un montant.");const receipt=expenseReceiptRemoved?"":pendingExpenseReceipt?.dataUrl||prev?.receiptDataUrl||"",rn=expenseReceiptRemoved?"":pendingExpenseReceipt?.name||prev?.receiptName||"";const row={id:id||uid(),date:$("#d_date").value,cat:window._dcat||S().cats[0],desc:$("#d_desc").value.trim(),montant:+$("#d_m").value,tva:+$("#d_tva").value};if(receipt){row.receiptDataUrl=receipt;row.receiptName=rn}upsert("depenses",row);pendingExpenseReceipt=null;expenseReceiptRemoved=false;expenseEditingId="";if(!id)cloudTrackUsageEvent("expense_created");toast("Dépense enregistrée")}
/* Factures */
function editF(_,cid){const c=db.courses.find(x=>x.id===cid)||{};modal(sheet({title:"Nouveau document",body:`<div class="fields"><div class="field"><span class="label">Type</span><div class="seg" id="f_kind"><button type="button" aria-pressed="true" data-v="Facture" onclick="pickSeg(this)">Facture</button><button type="button" aria-pressed="false" data-v="Devis" onclick="pickSeg(this)">Devis</button></div></div><div class="field"><label for="f_cl">Client</label><select id="f_cl"><option value="">Choisir un client</option>${db.clients.map(x=>`<option value="${esc(x.id)}" ${x.id===c.client?"selected":""}>${esc(x.nom)}</option>`).join("")}</select></div><div class="field"><label for="f_desc">Désignation</label><textarea id="f_desc" rows="2">${esc(c.id?designOf(c):"")}</textarea></div><div class="field"><label for="f_tot">Montant TTC</label><div class="input-group"><input id="f_tot" type="number" inputmode="decimal" step="0.01" min="0" value="${esc(c.prix||"")}" style="font-size:20px;font-weight:800"><span class="suffix">€</span></div></div></div>`,foot:`<button class="btn secondary" onclick="close_()">Annuler</button><button class="btn" onclick="saveF('${esc(cid||"")}')">Créer le document</button>`}));setTimeout(()=>segThumb($("#f_kind")),30)}
function saveF(cid){const t=+$("#f_tot").value;if(!t)return toast("Saisissez un montant.");const dv=$("#f_kind [aria-pressed=true]").dataset.v==="Devis";const o=touch({id:uid(),...nextNum(dv?S().prefixDevis:S().prefix),date:today(),client:$("#f_cl").value,desc:$("#f_desc").value.trim(),total:t,statut:dv?"devis":"en attente",course:cid});db.factures.push(o);db.deleted=(db.deleted||[]).filter(x=>!(x.arr==="factures"&&x.id===o.id));save();cloudTrackUsageEvent("invoice_created");close_();setTimeout(()=>{go(true);viewF(o.id)},RM.matches?0:320)}
function editInvoice(id){const x=db.factures.find(q=>q.id===id);if(!x)return toast("Document introuvable");const dev=x.statut==="devis";modal(sheet({title:`Modifier ${esc(x.num)}`,body:`<p class="note box">Le numéro ${esc(x.num)} est conservé pour la traçabilité.</p><div class="fields"><div class="row-2"><div class="field"><label for="fi1">Date</label><input id="fi1" type="date" value="${esc(x.date||today())}"></div><div class="field"><label for="fi4">Montant TTC</label><div class="input-group"><input id="fi4" type="number" inputmode="decimal" step="0.01" value="${esc(x.total)}"><span class="suffix">€</span></div></div></div><div class="field"><label for="fi2">Client</label><select id="fi2"><option value="">—</option>${db.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===x.client?"selected":""}>${esc(c.nom)}</option>`).join("")}</select></div><div class="field"><label for="fi3">Désignation</label><textarea id="fi3" rows="3">${esc(x.desc||"")}</textarea></div><div class="field"><span class="label">Statut</span><div class="seg" id="fi6">${[["devis","Devis"],["en attente","À encaisser"],["payée","Payée"]].map(([v,l])=>`<button type="button" data-v="${v}" aria-pressed="${x.statut===v}" onclick="pickSeg(this)">${l}</button>`).join("")}</div></div></div>`,foot:`<button class="btn secondary" onclick="close_()">Annuler</button><button class="btn" onclick="saveInvoice('${esc(x.id)}')">Enregistrer</button>`}));setTimeout(()=>segThumb($("#fi6")),30)}
function saveInvoice(id){const x=db.factures.find(q=>q.id===id);if(!x)return;const total=+$("#fi4").value;if(!total)return toast("Saisissez un montant.");x.date=$("#fi1").value||today();x.client=$("#fi2").value;x.desc=$("#fi3").value.trim();x.total=total;x.statut=$("#fi6 [aria-pressed=true]")?.dataset.v||x.statut;touch(x);db.deleted=(db.deleted||[]).filter(q=>!(q.arr==="factures"&&q.id===x.id));save();close_();go(true);toast("Document modifié")}
function viewF(id){const x=db.factures.find(q=>q.id===id);if(!x)return toast("Document introuvable");const c=cl(x.client),co=db.courses.find(q=>q.id===x.course),t=(c.tel||"").replace(/[\s.\-]/g,""),m=co?msgFact(co,x):fill(S().msgFact,{client:c.nom,nom:S().nom,num:x.num,total:eur(x.total),statut:x.statut==="payée"?"réglée":"à régler"});
  modal(sheet({title:`${x.statut==="devis"?"Devis":"Facture"} ${esc(x.num)}`,body:`<section class="card" style="display:grid;gap:10px"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px"><div><span class="eyebrow">${esc(clientName(x.client))}</span><b class="serif tnum" style="font-size:40px;line-height:1">${eur(x.total)}</b></div><span class="pill ${x.statut==="payée"?"ok":x.statut==="devis"?"":"warn"}">${esc(x.statut)}</span></div><div class="kv"><div><span>Date</span><b>${fd(x.date)}</b></div><div><span>Désignation</span><b style="max-width:60%">${esc(x.desc||"—")}</b></div>${co?`<div><span>Course</span><b><a href="#course/${esc(co.id)}">${fd(co.date)} ${esc(co.heure||"")}</a></b></div>`:""}</div></section>
  ${x.statut==="en attente"?`<button class="btn lg block" onclick="payF('${esc(id)}')">${icon("check")} Marquer comme payée</button>`:""}
  <section class="card pad-0"><div class="list"><button class="item" onclick="pdfShare('${esc(id)}')"><span class="ico brand">${icon("share")}</span><span><b>Envoyer le PDF</b><small>Partager ou enregistrer</small></span>${icon("right","chev")}</button><button class="item" onclick="pdfDown('${esc(id)}')"><span class="ico">${icon("down")}</span><span><b>Télécharger le PDF</b></span>${icon("right","chev")}</button>${t?`<a class="item" href="https://wa.me/${intl(t)}?text=${enc(m)}" target="_blank" rel="noopener"><span class="ico">${icon("msg")}</span><span><b>Message WhatsApp</b></span>${icon("right","chev")}</a><a class="item" href="sms:${esc(t)}?body=${enc(m)}"><span class="ico">${icon("mail")}</span><span><b>SMS</b></span>${icon("right","chev")}</a>`:""}<button class="item" onclick="editInvoice('${esc(id)}')"><span class="ico">${icon("edit")}</span><span><b>Modifier</b></span>${icon("right","chev")}</button></div></section>
  <button class="btn ghost" onclick="confirmTap(this,()=>removeRecord('factures','${esc(id)}'),'Confirmer la suppression')">${icon("trash")} Supprimer le document</button>`}))}
function payF(id){const x=db.factures.find(q=>q.id===id);if(!x)return;x.statut="payée";touch(x);db.deleted=(db.deleted||[]).filter(q=>!(q.arr==="factures"&&q.id===id));save();close_();go(true);toast("Facture marquée payée")}

/* ════════════ DOCUMENTS ════════════ */
views.documents=()=>{const docs=[...db.docs].sort((a,b)=>(a.exp||"9999").localeCompare(b.exp||"9999"));return`<div class="page"><a class="crumb" href="#plus">${icon("left")} Plus</a><div class="head"><div><span class="eyebrow">Échéances</span><h1>Documents</h1><p>Carte pro, assurance, contrôle technique : soyez prévenu 30 jours avant l’expiration.</p></div><button class="btn" onclick="editDoc()">${icon("plus")} Ajouter</button></div>
  ${docs.length?`<section class="card pad-0"><div class="list">${docs.map(d=>{const days=d.exp?Math.ceil((new Date(d.exp)-new Date())/864e5):null,cls=days==null?"":days<0?"danger":days<30?"warn":"ok",lbl=days==null?"Sans échéance":days<0?`Expiré depuis ${-days} j`:days===0?"Expire aujourd’hui":`Dans ${days} j`;return`<button class="item" onclick="editDoc('${esc(d.id)}')"><span class="ico ${cls==="ok"?"brand":cls}">${icon("file")}</span><span><b>${esc(d.nom||"Document")}</b><small>${d.exp?"Échéance le "+fd(d.exp):"Aucune date"}</small></span><span class="pill ${cls}">${lbl}</span></button>`}).join("")}</div></section>`:`<div class="card flat"><div class="empty"><span class="ico">${icon("file")}</span><b>Aucun document</b><p>Ajoutez vos documents et leur date d’expiration : l’accueil vous préviendra à temps.</p></div></div>`}</div>`};
function editDoc(id){const d=db.docs.find(x=>x.id===id)||{};modal(sheet({title:id?"Modifier le document":"Nouveau document",body:`<div class="fields"><div class="field"><label for="o_nom">Nom</label><input id="o_nom" value="${esc(d.nom||"")}" placeholder="Carte professionnelle VTC"></div><div class="field"><label for="o_exp">Date d’expiration</label><input id="o_exp" type="date" value="${esc(d.exp||"")}"></div>${id?`<button class="btn ghost" onclick="askDelete('docs','${esc(id)}',this)">${icon("trash")} Supprimer</button>`:""}</div>`,foot:`<button class="btn secondary" onclick="close_()">Annuler</button><button class="btn" onclick="saveDoc('${esc(id||"")}')">Enregistrer</button>`}))}
function saveDoc(id){if(!$("#o_nom").value.trim())return toast("Donnez un nom au document.");upsert("docs",{id:id||uid(),nom:$("#o_nom").value.trim(),exp:$("#o_exp").value});toast("Document enregistré")}

/* ════════════ PLUS / COMPTE / DONNÉES ════════════ */
views.plus=()=>{const isAdmin=typeof adminAccess!=="undefined"&&!!adminAccess,t=(h,ic,cls,b,s)=>`<a class="tile" href="#${h}"><span class="ico ${cls}">${icon(ic)}</span><span><b>${b}</b><small>${s}</small></span>${icon("right","chev")}</a>`;
  return`<div class="page"><div class="head"><div><span class="eyebrow">Votre espace</span><h1>Plus</h1></div></div>
  ${typeof billingPlusCardHTML==="function"?billingPlusCardHTML():""}
  <div class="hub stagger">${t("clients","users","brand","Clients",`${plural(db.clients.length,"fiche")}`)}${t("documents","file","","Documents","Échéances et rappels")}${t("finances","wallet","","Finances","Factures, dépenses, résultat")}${t("data","cloud","","Données et synchronisation","Sauvegarde Excel, notifications")}${t("settings","gear","","Paramètres","Entreprise, factures, tarifs")}${t("account","user","","Mon compte",typeof cloudUser!=="undefined"&&cloudUser?esc(cloudUser.email):"Connexion")}${isAdmin?t("admin","shield","gold","Administration","CRM, abonnements, comptes"):""}<button class="tile" onclick="slmInstall()"><span class="ico">${icon("install")}</span><span><b>Installer l’application</b><small>Icône sur l’écran d’accueil</small></span>${icon("right","chev")}</button></div>
  <p class="faint" style="text-align:center;font-size:12px">SLM Transfert · version ${APP_VERSION}</p></div>`};
views.account=()=>{const u=typeof cloudUser!=="undefined"?cloudUser:null;return`<div class="page"><a class="crumb" href="#plus">${icon("left")} Plus</a><div class="head"><div style="display:flex;gap:14px;align-items:center"><span class="avatar" style="width:56px;height:56px;font-size:22px">${esc(initial(u?.email||"S"))}</span><div><span class="eyebrow">Mon compte</span><h1 style="font-size:30px;word-break:break-all">${esc(u?.email||"Non connecté")}</h1></div></div></div>
  ${typeof billingAccountCardHTML==="function"?billingAccountCardHTML():""}
  <section class="card"><div class="card-head"><h3>Synchronisation</h3><span class="pill ok" id="accountCloudStatus" data-state="ok"><i></i>${esc(typeof cloudMsg!=="undefined"&&cloudMsg||"Connecté")}</span></div><p class="note">Vos courses, clients, factures et réglages sont identiques sur tous les appareils connectés à ce compte.</p><div class="btn-row" style="margin-top:12px"><button class="btn secondary" onclick="cloudPull(true)">${icon("sync")} Synchroniser</button><button class="btn ghost" onclick="cloudLogout()">${icon("out")} Se déconnecter</button></div></section>
  ${u&&typeof billingAccountPrivacyHTML==="function"?billingAccountPrivacyHTML():""}
  <section class="card pad-0"><div class="list"><a class="item" href="#premium"><span class="ico gold">${icon("spark")}</span><span><b>Abonnement et parrainage</b><small>Offre, paiements, mois offerts</small></span>${icon("right","chev")}</a><a class="item" href="#data"><span class="ico">${icon("cloud")}</span><span><b>Données</b><small>Export et restauration Excel</small></span>${icon("right","chev")}</a><a class="item" href="#settings"><span class="ico">${icon("gear")}</span><span><b>Paramètres</b></span>${icon("right","chev")}</a>${typeof adminAccess!=="undefined"&&adminAccess?`<a class="item" href="#admin"><span class="ico gold">${icon("shield")}</span><span><b>Administration</b><small>CRM et gestion des comptes</small></span>${icon("right","chev")}</a>`:""}</div></section></div>`};
function pushTile(){const on=typeof pushDeviceActive==="function"&&pushDeviceActive();return`<button class="item" onclick="${on?"disablePushNotifications()":"askNotif()"}"><span class="ico ${on?"brand":"warn"}">${icon("bell")}</span><span><b>${on?"Rappels actifs sur cet appareil":"Activer les rappels sur cet appareil"}</b><small>${on?"Touchez pour désactiver":"Notification avant chaque course, même application fermée"}</small></span>${on?`<span class="pill ok">Actif</span>`:icon("right","chev")}</button>`}
views.data=()=>{const u=typeof cloudUser!=="undefined"?cloudUser:null;return`<div class="page"><a class="crumb" href="#plus">${icon("left")} Plus</a><div class="head"><div><span class="eyebrow">Application</span><h1>Données et synchronisation</h1><p>Vos données sont synchronisées avec votre compte. Gardez aussi une copie Excel de temps en temps.</p></div></div>
  <section class="card"><div class="card-head"><h3>Compte synchronisé</h3><small id="cloudStatus" data-state="ok">${esc(typeof cloudMsg!=="undefined"&&cloudMsg||"Connecté")}</small></div><p class="note">${esc(u?.email||"")}</p><div class="btn-row" style="margin-top:12px"><button class="btn secondary" onclick="cloudPull(true)">${icon("sync")} Synchroniser maintenant</button></div></section>
  <section class="card pad-0"><div class="list"><button class="item" onclick="exportAppExcel(true)"><span class="ico brand">${icon("down")}</span><span><b>Exporter toute l’application</b><small>Classeur Excel complet, restaurable</small></span>${icon("right","chev")}</button><button class="item" onclick="openExcelImport()" ${u?"":"disabled"}><span class="ico">${icon("up")}</span><span><b>Importer ou restaurer un Excel</b><small>Dans le compte connecté</small></span>${icon("right","chev")}</button>${pushTile()}<button class="item" onclick="icsAll()"><span class="ico">${icon("cal")}</span><span><b>Exporter le planning</b><small>Fichier agenda (.ics) des courses à venir</small></span>${icon("right","chev")}</button></div></section>
  <input id="slm-excel-import" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden onchange="importExcelFile(this.files[0])">
  <p class="note box">L’export contient des onglets lisibles et une feuille de restauration masquée. Vos identifiants et clés de paiement ne sont jamais exportés. Le fichier contient les coordonnées de vos clients : gardez-le dans un endroit privé.</p></div>`};
function showExcelImportPreview(data,name){const counts=[["Courses",data.courses?.length||0],["Clients",data.clients?.length||0],["Factures et devis",data.factures?.length||0],["Dépenses",data.depenses?.length||0],["Documents",data.docs?.length||0]];modal(sheet({title:"Importer le fichier",body:`<p class="note">${esc(name)} → compte <b>${esc(cloudUser?.email||"")}</b></p><section class="card"><div class="kv">${counts.map(([l,n])=>`<div><span>${l}</span><b>${n}</b></div>`).join("")}</div></section><section class="card pad-0"><div class="list"><button class="item" onclick="applyExcelImport('merge')"><span class="ico brand">${icon("sync")}</span><span><b>Fusionner</b><small>Ajoute les fiches du fichier, garde la version la plus récente</small></span>${icon("right","chev")}</button><button class="item" onclick="confirmTap(this,()=>applyExcelImport('replace'),'Confirmer le remplacement')"><span class="ico danger">${icon("alert")}</span><span><b>Remplacer toutes les données</b><small>Définitif pour les données actuelles du compte</small></span>${icon("right","chev")}</button></div></section>`,foot:`<button class="btn secondary" onclick="pendingExcelRestore=null;close_()">Annuler</button>`}))}

/* ════════════ PARAMÈTRES ════════════ */
let openSets=new Set(["ent"]);
function openSet(id){const d=document.getElementById("set-"+id);if(d){d.open=true;openSets.add(id);d.scrollIntoView({behavior:RM.matches?"auto":"smooth",block:"start"})}}
function setS(k,v){if(k==="costKm"&&typeof billingRequirePremium==="function"&&!billingRequirePremium("monthly_report"))return;db.settings[k]=v;db.meta=db.meta||{};db.meta.settingsAt=Date.now();save();if(k==="appearance")applyTheme()}
function setL(k,v){db.settings[k]=v.split("\n").map(x=>x.trim()).filter(Boolean);db.meta=db.meta||{};db.meta.settingsAt=Date.now();save()}
const hint=h=>h?`<span class="hint">${h}</span>`:"";
const fT=(k,l,h,type="text")=>`<div class="field"><label for="s_${k}">${l}</label><input id="s_${k}" type="${type}" value="${esc(S()[k])}" onchange="setS('${k}',this.value)">${hint(h)}</div>`;
const fN=(k,l,h,suf)=>`<div class="field"><label for="s_${k}">${l}</label><div class="input-group"><input id="s_${k}" type="number" inputmode="decimal" step="any" value="${esc(S()[k])}" onchange="setS('${k}',+this.value)">${suf?`<span class="suffix">${suf}</span>`:""}</div>${hint(h)}</div>`;
const fC=(k,l,s)=>`<label class="switch"><span>${l}${s?`<small>${s}</small>`:""}</span><input type="checkbox" ${S()[k]?"checked":""} onchange="setS('${k}',this.checked)"><i></i></label>`;
const fS=(k,l,o,h)=>`<div class="field"><label for="s_${k}">${l}</label><select id="s_${k}" onchange="setS('${k}',this.value)">${o.map(x=>`<option value="${esc(x[0])}" ${String(S()[k])===String(x[0])?"selected":""}>${esc(x[1])}</option>`).join("")}</select>${hint(h)}</div>`;
const fA=(k,l,h,r=3)=>`<div class="field"><label for="s_${k}">${l}</label><textarea id="s_${k}" rows="${r}" onchange="setS('${k}',this.value)">${esc(S()[k])}</textarea>${hint(h)}</div>`;
const fL=(k,l,h)=>`<div class="field"><label for="s_${k}">${l}</label><textarea id="s_${k}" rows="5" onchange="setL('${k}',this.value)">${esc((S()[k]||[]).join("\n"))}</textarea>${hint(h)}</div>`;
const setBlock=(id,ic,title,sub,body)=>`<details class="set" id="set-${id}" ${openSets.has(id)?"open":""} ontoggle="this.open?openSets.add('${id}'):openSets.delete('${id}')"><summary><span class="ico">${icon(ic)}</span><span><b>${title}</b><small>${sub}</small></span>${icon("right","chev")}</summary><div class="in">${body}</div></details>`;
function companyFiscalHTML(){const s=S(),sel=(id,l,o,v)=>`<div class="field"><label for="${id}">${l}</label><select id="${id}">${o.map(([a,b])=>`<option value="${esc(a)}" ${String(v)===a?"selected":""}>${esc(b)}</option>`).join("")}</select></div>`;
  return`<form id="company-fiscal-form" class="fields" onsubmit="saveCompanyFiscal(event)"><p class="note">Le statut juridique ne détermine pas à lui seul la TVA ni les cotisations : confirmez chaque régime.</p>${sel("business-form","Statut de l’entreprise",BUSINESS_FORMS,s.businessForm||"")}<div class="field"><label for="business-other">Précision (facultatif)</label><input id="business-other" maxlength="100" value="${esc(s.businessOther||"")}"></div><button type="button" class="btn soft" onclick="suggestCompanyRegime()">Proposer le calcul adapté</button>${sel("business-tax","Imposition des bénéfices",[["","À confirmer"],["micro","Micro-BIC"],["ir","Impôt sur le revenu (IR)"],["is","Impôt sur les sociétés (IS)"]],s.businessTax||"")}<div class="row-2">${sel("business-vat","TVA",[["off","Franchise en base"],["on","Redevable de la TVA"]],s.tvaOn?"on":"off")}<div class="field"><label for="business-vat-rate">Taux de TVA</label><div class="input-group"><input id="business-vat-rate" type="number" min="0" max="100" step="0.01" required value="${+s.tva||0}"><span class="suffix">%</span></div></div></div>${sel("business-social","Calcul des cotisations",SOCIAL_MODES,s.socialMode||"legacy")}<div class="field"><label for="business-social-rate">Taux personnalisé ou ACRE confirmé</label><div class="input-group"><input id="business-social-rate" type="number" min="0" max="100" step="0.01" required value="${Number.isFinite(+s.cotis)?+s.cotis:21.2}"><span class="suffix">%</span></div></div><label class="switch"><span>Utiliser mon taux personnalisé en micro-BIC<small>ACRE ou situation confirmée</small></span><input id="business-custom-rate" type="checkbox" ${s.microCustomRate?"checked":""}><i></i></label><p class="note">Micro-BIC : taux standard de 21,2 % en 2026, hors formation professionnelle, taxes consulaires et impôt. Les chiffres sont des prévisions sur les courses saisies, pas des déclarations. <a href="https://mon-entreprise.urssaf.fr/simulateurs" target="_blank" rel="noopener">Simulateurs Urssaf</a></p><button type="submit" class="btn">Enregistrer mon statut</button><p id="business-save-status" role="status" class="hint"></p></form>`}
function suggestCompanyRegime(){const form=$("#business-form").value;if(!form)return toast("Choisissez d’abord votre statut.");const micro=form==="micro";$("#business-social").value=micro?"micro_bic":"recorded";if(micro){$("#business-social-rate").value="21.2";$("#business-custom-rate").checked=false;$("#business-tax").value="micro"}else $("#business-tax").value="";$("#business-save-status").textContent="Proposition prête. Confirmez la TVA et le régime fiscal, puis enregistrez."}
function saveCompanyFiscal(ev){ev.preventDefault();const form=$("#company-fiscal-form");if(!form.reportValidity())return;const g=id=>$("#"+id).value,mode=g("business-social"),custom=$("#business-custom-rate").checked,rate=+g("business-social-rate"),vat=+g("business-vat-rate");
  if(!Number.isFinite(rate)||rate<0||rate>100||!Number.isFinite(vat)||vat<0||vat>100)return toast("Saisissez des taux entre 0 et 100 %.");
  if(mode==="micro_bic"&&!["micro","ei","eurl"].includes(g("business-form")))return toast("Le micro-BIC concerne l’EI ou une EURL éligible.");
  if(mode==="micro_bic"&&g("business-tax")!=="micro")return toast("Confirmez le régime fiscal Micro-BIC.");
  Object.assign(db.settings,{businessForm:g("business-form"),businessOther:g("business-other").trim(),businessTax:g("business-tax"),socialMode:mode,microCustomRate:custom,tvaOn:g("business-vat")==="on",tva:vat,cotis:mode==="micro_bic"&&!custom?21.2:rate});if(!db.settings.cats.includes("Cotisations"))db.settings.cats.push("Cotisations");db.meta.settingsAt=Date.now();save();$("#business-social-rate").value=S().cotis;$("#business-save-status").textContent="Enregistré. Vos estimations utilisent ces choix.";toast("Statut enregistré")}
function reminderPickerHTML(){const sel=offs(),extra=sel.filter(n=>n>1440||n%60!==0);return`<div class="field"><span class="label">Rappels avant chaque course</span><select id="reminder-preset" aria-label="Préréglage des rappels" onchange="if(this.value!==''){setReminderPreset(+this.value);this.value=''}"><option value="">Préréglage…</option>${[[1,"Toutes les heures"],[2,"Toutes les 2 h"],[3,"Toutes les 3 h"],[0,"Aucun rappel"]].map(([n,l])=>`<option value="${n}">${l}</option>`).join("")}</select><div class="checks">${Array.from({length:24},(_,i)=>i+1).map(h=>`<label><input type="checkbox" data-reminder="${h*60}" ${sel.includes(h*60)?"checked":""} onchange="setReminderChoice(${h*60},this.checked)">${h} h</label>`).join("")}${extra.map(n=>`<label><input type="checkbox" data-reminder="${n}" checked onchange="setReminderChoice(${n},this.checked)">${labM(n)}</label>`).join("")}</div><span id="reminder-selection" class="hint" role="status">${reminderSelectionText(sel)}</span></div>`}
function reminderSelectionText(v){return v.length?`Rappels ${v.map(labM).join(" · ")} avant chaque course.`:"Aucun rappel ne sera programmé."}
function storeReminderChoices(values){const s=[...new Set(values)].filter(n=>Number.isInteger(n)&&n>0&&n<=43200).sort((a,b)=>b-a);setS("rappels",s.join(","));document.querySelectorAll("[data-reminder]").forEach(i=>i.checked=s.includes(+i.dataset.reminder));const n=$("#reminder-selection");if(n)n.textContent=reminderSelectionText(s)}
function setReminderChoice(m,c){storeReminderChoices(c?[...offs(),m]:offs().filter(n=>n!==m))}
function setReminderPreset(step){storeReminderChoices(step?Array.from({length:24},(_,i)=>(i+1)*60).filter(n=>(n/60)%step===0):[])}
async function previewPdf(kind){const s=S();const inv={id:"x",num:fmtNum(kind==="d"?s.prefixDevis:s.prefix,new Date().getFullYear(),1),date:today(),client:"",desc:fill(s.designTpl,{depart:"Aéroport de Genève",arrivee:"Annecy centre",date:fd(today()),heure:"09:00",client:"Client exemple",km:"46"}),total:120.5,statut:kind==="d"?"devis":kind==="p"?"payée":"en attente",course:""};const blob=await buildInvoicePdf(inv,{nom:"Client exemple",adresse:"1 rue Exemple, 74000 Annecy",tel:"06 00 00 00 00",email:"client@exemple.fr",siret:""},{date:today(),paiement:"CB"});dl("apercu-"+(kind==="d"?"devis":"facture")+".pdf",blob,"application/pdf");toast("Aperçu enregistré dans vos téléchargements")}
function resetPdfSettings(){Object.keys(def.settings).filter(k=>k.startsWith("pdf")||["prefix","prefixDevis","numFormat","numPad","numStart","designTpl","mentions"].includes(k)).forEach(k=>db.settings[k]=JSON.parse(JSON.stringify(def.settings[k])));db.meta.settingsAt=Date.now();save();refresh();toast("Réglages de facture réinitialisés")}
views.settings=()=>{const s=S(),prem=typeof billingCanUsePremium==="function"&&billingCanUsePremium();
  const ent=setBlock("ent","user","Coordonnées de l’entreprise","Reprises sur vos factures et devis",`<div class="row-2">${fT("nom","Nom de l’entreprise")}${fT("gerant","Nom du gérant")}</div>${fA("adresse","Adresse professionnelle","",2)}<div class="row-2">${fT("siret","SIRET")}${fT("tel","Téléphone","","tel")}</div><div class="row-2">${fT("email","E-mail","","email")}${fT("site","Site web","","url")}</div><div class="row-2">${fT("numCarte","Carte professionnelle")}${fT("plaque","Immatriculation")}</div>${fT("assurance","Assurance professionnelle")}${fT("iban","IBAN","Affiché sur les factures à régler")}`);
  const fis=setBlock("fiscal","shield","Statut, TVA et cotisations","Pour des estimations justes",companyFiscalHTML());
  const fac=setBlock("fac","receipt","Numérotation et contenu des factures","Préfixes, mentions, automatismes",`<div class="row-2">${fT("prefix","Préfixe facture")}${fT("prefixDevis","Préfixe devis")}</div>${fT("numFormat","Format du numéro","{P} préfixe, {Y} année, {N} numéro. Ex. F-2026-0001")}<div class="row-2">${fN("numPad","Chiffres du numéro","4 → 0001")}${fN("numStart","Premier numéro")}</div>${fT("designTpl","Désignation automatique","Variables : {depart} {arrivee} {date} {heure} {client} {km}")}<div class="row-2">${fT("pdfTitleF","Titre des factures")}${fT("pdfTitleD","Titre des devis")}</div>${fA("pdfIntro","Texte d’introduction","Facultatif",2)}<div class="row-2">${fT("pdfEcheance","Délai de paiement")}${fN("pdfDevisJours","Validité des devis","",  "jours")}</div>${fT("pdfThanks","Remerciement (facture payée)")}${fA("pdfPayInfo","Moyens de paiement acceptés","",2)}${fA("mentions","Mentions légales",null,4)}${fT("pdfFooter","Pied de page","Vide = nom, SIRET et e-mail")}<div>${fC("autoFacture","Créer la facture en terminant une course")}${fC("autoPdf","Télécharger le PDF automatiquement")}</div>${fL("payesAuto","Paiements considérés comme réglés","Un mode par ligne")}`);
  const pdf=setBlock("pdf","file","Présentation des PDF","Couleur, informations visibles, aperçu",`${fS("pdfStyle","Style de l’en-tête",[["band","Bandeau coloré"],["clean","Sobre"]])}<div class="field"><label for="s_pdfColor">Couleur principale</label><input id="s_pdfColor" type="color" value="${esc(s.pdfColor)}" onchange="setS('pdfColor',this.value)"></div><div>${[["pdfShowGerant","Nom du gérant"],["pdfShowAdresse","Adresse"],["pdfShowSiret","SIRET"],["pdfShowTel","Téléphone"],["pdfShowEmail","E-mail"],["pdfShowSite","Site web"],["pdfShowCarte","Carte professionnelle"],["pdfShowPlaque","Immatriculation"],["pdfShowAssurance","Assurance"],["pdfClientTel","Téléphone du client"],["pdfClientEmail","E-mail du client"],["pdfShowDate","Date de la prestation"],["pdfShowPay","Mode de paiement"],["pdfShowEcheance","Échéance"],["pdfCols","Colonnes HT et TVA"],["pdfShowIban","IBAN sur les factures à régler"],["pdfShowMentions","Mentions légales"]].map(([k,l])=>fC(k,l)).join("")}</div><div class="btn-row"><button class="btn soft" onclick="previewPdf('f')">Aperçu facture</button><button class="btn soft" onclick="previewPdf('p')">Facture payée</button><button class="btn soft" onclick="previewPdf('d')">Devis</button></div><button class="btn ghost" onclick="confirmTap(this,resetPdfSettings,'Confirmer la réinitialisation')">Réinitialiser ces réglages</button>`);
  const tar=setBlock("tar","euro","Tarifs et calculs","Prix automatique, commission, objectif",`<div class="row-3">${fN("tarifBase","Prise en charge","","€")}${fN("tarifKm","Prix au km","","€")}${fN("tarifMin","Prix minimum","","€")}</div>${fN("commPct","Commission plateforme","Appliquée au type « Plateforme » si la commission est vide","%")}${prem?fN("costKm","Coût variable par km","Carburant, entretien, usure. Sert au calcul de votre marge.","€"):`<button type="button" class="locked-feature" onclick="billingShowPremiumGate('monthly_report')"><span class="ico gold">${icon("trend")}</span><span><b>Coût réel au kilomètre</b><small>Affinez le calcul de votre marge avec votre coût réel.</small></span><span class="badge-premium">${icon("lock")} PREMIUM</span></button>`}${fN("objectif","Objectif de chiffre d’affaires mensuel","","€")}`);
  const lst=setBlock("lst","list","Listes et valeurs par défaut","Types, paiements, catégories",`${fL("types","Types de course","Un par ligne")}${fL("paiements","Modes de paiement","Un par ligne")}${fL("cats","Catégories de dépenses","Un par ligne")}<div class="row-2">${fS("typeDef","Type par défaut",s.types.map(x=>[x,x]))}${fS("payDef","Paiement par défaut",s.paiements.map(x=>[x,x]))}</div>${fN("dureeMin","Durée dans l’agenda","0 = calculée depuis les km","min")}`);
  const rap=setBlock("rap","bell","Rappels de course","Notifications avant chaque départ",`${fC("rappelsOn","Activer les rappels")}${reminderPickerHTML()}<section class="card pad-0 flat"><div class="list">${pushTile()}</div></section><p class="note">Les rappels en arrière-plan nécessitent l’autorisation des notifications sur chaque appareil. Sur iPhone, installez d’abord l’application sur l’écran d’accueil.</p>`);
  const msg=setBlock("msg","msg","Messages aux clients","Confirmation, facture, arrivée",`${fA("msgConfirm","Confirmation de course",null,4)}${fA("msgFact","Envoi de facture",null,3)}${fA("msgArrive","Message d’arrivée",null,2)}<p class="note">Variables : {client} {date} {heure} {depart} {arrivee} {prix} {paiement} {km} {nom} {num} {total} {statut}</p>`);
  const aff=setBlock("aff","home","Affichage","Thème et accueil",`<div class="field"><label for="s_appearance">Apparence</label><select id="s_appearance" onchange="setS('appearance',this.value)">${[["system","Automatique"],["light","Clair"],["dark","Sombre"]].map(([v,l])=>`<option value="${v}" ${(s.appearance||"system")===v?"selected":""}>${l}</option>`).join("")}</select></div><div>${fC("showChart","Graphique du chiffre d’affaires")}${fC("showObjectif","Objectif mensuel")}${fC("showUnpaid","Factures à encaisser")}</div>`);
  const sec_=setBlock("sec","lock","Code et verrouillage","Protection de cet appareil",`<label class="switch"><span>Rester connecté sur cet appareil<small>Ouvre l’application sans code, sur cet appareil uniquement</small></span><input type="checkbox" ${typeof deviceNoPin==="function"&&deviceNoPin()?"checked":""} onchange="slmSetRemember(this.checked);toast(this.checked?'Cet appareil restera connecté sans code':'Le code sera demandé à l’ouverture')"><i></i></label>${fC("pinOn","Demander le code à l’ouverture")}${fN("lockMin","Verrouiller après une absence de","0 = jamais","min")}<div class="btn-row"><button class="btn secondary" onclick="changePin()">Changer mon code</button><button class="btn secondary" onclick="lock()">Verrouiller maintenant</button></div>`);
  const dat=setBlock("dat","trash","Effacer la copie de cet appareil","Les données du compte restent en ligne",`<p class="note">Supprime la copie locale de ce navigateur. Les données synchronisées dans votre compte ne sont pas touchées.</p><button class="btn danger" onclick="confirmTap(this,resetAll,'Confirmer l’effacement')">Effacer les données de ce navigateur</button>`);
  return`<div class="page"><a class="crumb" href="#plus">${icon("left")} Plus</a><div class="head"><div><span class="eyebrow">Personnalisation</span><h1>Paramètres</h1><p>Enregistrés automatiquement et synchronisés sur vos appareils.</p></div></div>
  <section class="set-group"><h2>Entreprise</h2>${ent}${fis}</section><section class="set-group"><h2>Facturation</h2>${fac}${pdf}</section><section class="set-group"><h2>Courses</h2>${tar}${lst}${rap}${msg}</section><section class="set-group"><h2>Application</h2>${aff}${sec_}${dat}</section>
  <p class="faint" style="text-align:center;font-size:12px">Version ${APP_VERSION} · ${plural(db.courses.length,"course")} · ${plural(db.clients.length,"client")} · ${plural(db.factures.length,"facture")}</p></div>`};
/* ════════════ Divers ════════════ */
async function askNotif(){if(typeof enablePushNotifications!=="function")return toast("Le service de notifications n’est pas chargé.");return enablePushNotifications()}
connectionStatus();
